INSERT INTO public.content_blocks
SELECT * FROM jsonb_populate_recordset(NULL::public.content_blocks, '[{"id":"006f2c4d-459c-47ea-8cc6-8fc2c75e1f51","body":"6世紀末から7世紀初頭頃に築かれた全長約97メートルの前方後円墳。東国最大級の横穴式石室をもち、銅鏡・刀剣・馬具など多数の副葬品が出土しました。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"c9052369-f319-4885-beb5-9346f2d6c46f","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"0264d1e0-3c55-4331-a714-bdad93e087b1","body":"諏訪神社境内にある史跡です。参拝者や地域住民に配慮し、境内の見学可能範囲から見学してください。周辺の私有地には立ち入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"7c30c1f3-aa08-4e2c-9f37-1df1dc1b425c","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"0268674b-1b87-4090-9f8d-e9979bdf98bd","body":"毛野国白石丘陵公園の史跡エリアです。整備された見学経路を利用し、史跡保護のため立入制限や現地表示に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"a40bfeb6-0df2-4bb4-a0ad-9850c5b828b4","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"04cb6caa-37e6-4b2a-9a31-1fc5b2976f71","body":"群馬県は山地が多く、県境は山や川などの地形とも関係しています。地図を鶴に見立てることで、抽象的な県土の形が覚えやすい郷土イメージとして定着しました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"abf5e22e-43e5-4ad0-a255-73bde912bb8d","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"05ada1f5-aabf-4942-bbcb-3161387e34f1","body":"「え」の札は、高崎だるま発祥の地として知られる少林山達磨寺を詠んでいます。達磨寺は黄檗宗の寺院で、境内には達磨大師をまつる堂宇や、各地のだるまを展示する達磨堂があります。正月の七草大祭だるま市は、高崎を代表する年中行事の一つです。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.takasaki.gunma.jp/site/sightseeing/4374.html","https://www.city.takasaki.gunma.jp/site/cultural-assets/5358.html","https://www.city.takasaki.gunma.jp/uploaded/attachment/6705.pdf"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"f5d99680-ca79-4b71-98f7-c1a34e8862f9","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":20},{"id":"05b9086d-f9cf-43d9-b801-a143a829aecb","body":null,"role":"picture_card","title":"絵札","alt_text":"湯檜曽駅の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"c825159c-ceac-4323-953a-ce239e4513fa","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/る-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"06828488-d5bc-4a44-92d4-26343bba2d50","body":"塩原太助は実在の人物ですが、その生涯は講談や物語によって脚色され、庶民の理想像として広まりました。史実と物語が重なりながら地域の記憶になった人物です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"82c45584-ad11-45a5-b30c-0f2f5ebd9716","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"06db86fd-2f60-4978-bd71-c4fb8839ed71","body":null,"role":"reading_card","title":"読み札","alt_text":"ほの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"865acdc4-13bd-4f04-b3b5-2713d5353acc","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ほ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"085b2dca-a1ce-49f1-83ad-424a7000dee0","body":"世のちり洗う 四万温泉","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"432cd618-9f42-4472-82df-7f3cbe744eac","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"086a8d10-0a93-4a8d-bc9f-88b5f3d6c8a3","body":null,"role":"reading_card","title":"読み札","alt_text":"おの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"9554c6ed-0b93-45b0-a243-e9120cf67578","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/お-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"094564aa-864f-4766-b3bb-ee5d3fd1a8ae","body":"国指定史跡「総社古墳群」の一部です。前橋市の見学コースでも巡られている史跡です。寺社・個人所有地を含むため、現地の案内や立入範囲を守って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"25f6080f-6de6-4a0d-851d-d9a2d478e270","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"0a35f8a5-817c-4c15-9963-8bfea104eddf","body":"5世紀後半から6世紀初めの保渡田古墳群で最初に築かれた約100メートルの前方後円墳。発掘前の姿をできるだけ変えない方法で整備され、内堤・外堤は園路として利用されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"50f29b73-1714-48ca-aa8a-08de86d0a0fb","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"0b0e94ca-970d-43dd-b352-38d58d82215a","body":"桐生織物記念館では、桐生の織物産業の歩みや製品、技術に注目してみましょう。建物の周辺からでも、織物の町として発展した桐生の歴史をたどる起点になります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.kiryu.lg.jp/shisetsu/kankou/1012426/","https://kiryuorimonokinenkan.com/access/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"2ab7a19f-8e1f-4f67-9fc6-d087030037e0","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"0b663a77-17ee-4d4b-97fe-c4e476939585","body":"前橋の生糸産業は、単に町を豊かにしただけではありません。生糸商や製糸業者らの力は、前橋城の再築や県庁誘致、近代的なまちづくりにもつながりました。明治期には前橋が県都となり、製糸都市として成長します。市内には、日本最初期の洋式器械製糸所の跡を示す碑や、繭・生糸を保管した旧安田銀行担保倉庫、蚕糸業の研究を伝える前橋市蚕糸記念館などが残っています。今の前橋の街並みの奥には、生糸によって築かれた近代都市の記憶が重なっています。","role":"history","title":"生糸が県都をつくった","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.maebashi.gunma.jp/bunka_sports_kanko/7/3/1/11380.html","https://www.city.maebashi.gunma.jp/bunka_sports_kanko/7/5/11389.html"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"45e0a31d-0919-4f3a-a988-1a0002401d98","created_at":"2026-09-21T01:32:40.55618+00:00","media_path":null,"updated_at":"2026-09-21T01:32:40.55618+00:00","display_order":25},{"id":"0bc61612-5e4c-47e5-ada6-9e165cf1caf7","body":"総門をくぐったら、社殿へ向かって地面が下がっていくことに注目してください。建物の装飾だけでなく、地形を含めた境内全体を見ると、長く守られてきた信仰空間を感じられます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"2432646f-411c-4990-82b4-b311a88c03e7","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"0c69130c-3bca-4094-8d4c-a75bbe53e495","body":"「す」は、上毛三山の一つ赤城山の雄大な裾野を詠んでいます。複数の峰とカルデラ湖を持つ火山で、広い裾野は県央部の景観を特徴づけています。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"9f1da0c0-f3e4-4b84-a261-938dac68b1fc","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"0e276dac-963a-477a-8656-a817162df1b5","body":"「の」は、榛名山の自然と高原の行楽地としての魅力を詠んでいます。榛名湖を中心に登山、キャンプ、湖畔散策などを楽しめる地域として親しまれてきました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"3bf0c740-36ec-4a4c-a638-6664221bf83d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"0ea3882c-b37f-4f71-b5a8-d631caf28b19","body":"貫前神社は古代から地域の信仰の中心となり、現在の社殿にも歴史的価値があります。総門から石段を下って社殿へ向かう「下り宮」の配置も大きな特徴です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2432646f-411c-4990-82b4-b311a88c03e7","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"10258863-04a5-4a60-8a4d-66539f631841","body":"伊勢崎市指定史跡で、後円部頂上の富士神社付近に長持形石棺があります。神社境内と現地の案内に従い、周辺の住宅や私有地には立ち入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"6173eb40-396f-4b9e-a2b8-d48abe5949f3","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"124a2142-2009-4ed1-a6fb-da567fdec3dd","body":"吹割の滝では、指定された遊歩道や安全な観覧地点から渓谷と滝の流れを観察してください。水際へ近づく必要はありません。冬季や夜間など遊歩道が閉鎖されている場合は立ち入らず、現地の案内を優先してください。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"e08b235d-f74c-46ca-baa1-66a760ab4dfb","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"12572b8d-069a-452e-aa98-d68d2751fef4","body":"太田金山 子育呑龍","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"9554c6ed-0b93-45b0-a243-e9120cf67578","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"14ca779d-7229-4c1d-9c35-3841a1f68bfc","body":"「へ」は、安中ゆかりの教育者・新島襄を詠んでいます。幕末に海外へ渡って学び、帰国後に同志社英学校を創設し、近代日本の教育に大きな足跡を残しました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"10c77873-d75d-471c-99d4-737f4130c99c","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"1683441a-a892-49f4-a275-2c44de9b0607","body":"「さ」は、藤岡市鬼石地域を代表する三波石と冬桜を一緒に詠んでいます。三波石峡の美しい岩石と、冬にも花を咲かせる桜が地域の特徴として知られています。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"943686a4-a533-4e8c-bcb5-5a182e10984f","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"170465f4-2435-4722-b629-6ef385763c9b","body":null,"role":"reading_card","title":"読み札","alt_text":"れの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"d46c78a7-28a2-4ed5-ac94-7b4f3638d425","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/れ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"17b780b4-a54e-4878-8189-fd4f81d1b7e7","body":"田山花袋旧居では、花袋が少年期を過ごした生活の場そのものに触れられます。建物や周囲の町並みを見ながら、文豪になる以前の花袋と館林とのつながりを感じてみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.tatebayashi.gunma.jp/sp005/020/20210105163059.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"865acdc4-13bd-4f04-b3b5-2713d5353acc","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"17db8a47-6037-4689-8a64-e6e905781a4a","body":null,"role":"picture_card","title":"絵札","alt_text":"高崎駅の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"56c86827-bb9f-484e-b4a2-36b70aa2b2f1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/か-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"18886e1c-3cdc-4173-b52e-0cc766d825cd","body":"力あわせる 百九十万","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"3aaacece-c523-42a0-978f-e8c609800f0a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"199d0c7c-dcf5-446c-9233-b9406b412db5","body":"高崎の成長は交通と深く結び付いています。江戸時代の街道交通から鉄道時代へ、さらに新幹線・高速道路へと交通手段が変わっても、「人と物が集まり、各地へ分かれる場所」という役割は受け継がれています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"56c86827-bb9f-484e-b4a2-36b70aa2b2f1","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"1a4cd0de-fe32-4780-b3cb-494be19658bb","body":"現地では復元された東門だけでなく、石垣や関所跡の地形にも注目してください。近くの碓氷関所史料展示室では関所や近世交通の資料を見ることができます。さらに旧中山道を坂本宿や碓氷峠方向へたどると、「なぜここに関所が必要だったのか」を道そのものから感じられます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.annaka.lg.jp/page/2040.html","https://www.city.annaka.lg.jp/page/21633.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"1cb1876f-c1fb-4f16-9e11-0e6bedf45fe2","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":40},{"id":"1a80af1c-ef52-4199-b120-8bd82392bd17","body":"榛名湖では湖と榛名富士、周囲の外輪山の位置関係を見てみましょう。湖畔から山へ視線を上げると、キャンプや登山の舞台が火山地形の中にあることを実感できます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"3bf0c740-36ec-4a4c-a638-6664221bf83d","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"1c238b29-df2b-4be6-a172-8ffe1893e85f","body":"平和の使徒 新島襄","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"10c77873-d75d-471c-99d4-737f4130c99c","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"1dd67ae5-390d-4fa4-a27a-75c7ac9eb5ae","body":null,"role":"picture_card","title":"絵札","alt_text":"関孝和像・算聖の碑の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"2fb9ce0f-ebb8-417b-ae1d-bb2e7eecbed1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/わ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"1e82b5a4-8a0f-4b27-95db-08d5f33079d0","body":null,"role":"picture_card","title":"絵札","alt_text":"日本最初の器械製糸所跡の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"45e0a31d-0919-4f3a-a988-1a0002401d98","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/け-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"1ed7191d-339d-41c0-8a42-efd134d2b194","body":"内村鑑三は無教会主義を唱え、既成の教会制度に依存しない信仰のあり方を追究しました。信仰だけでなく戦争や社会の問題にも発言し、日本の近代思想に大きな足跡を残しています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"df0a6c5f-e5da-4538-a7e3-b369d427304c","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"1f9f3521-bec6-40d5-b62a-a30b3b5a3ed5","body":"住吉町一丁目の記念碑は、1870年に前橋藩が設けた日本最初の洋式器械製糸所の創設地を示します。国道17号沿いの碑を起点に、生糸産業が前橋の近代化と県都形成を支えた歴史をたどってみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.maebashi.gunma.jp/bunka_sports_kanko/7/3/1/11380.html"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"45e0a31d-0919-4f3a-a988-1a0002401d98","created_at":"2026-09-21T01:32:40.55618+00:00","media_path":null,"updated_at":"2026-09-21T01:32:40.55618+00:00","display_order":40},{"id":"20514506-372c-4e25-b0a0-6cf8ded455cd","body":"関東と信越つなぐ 高崎市","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"56c86827-bb9f-484e-b4a2-36b70aa2b2f1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"219fb8a1-d407-4985-8cf8-f0c33413e65a","body":null,"role":"picture_card","title":"絵札","alt_text":"茂左衛門地蔵尊の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"1f959c33-ef14-4fed-b456-a905ba73c009","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/て-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"21f61c44-a35c-4268-a730-5cddd05f711d","body":"大泉町の県指定史跡で、古海東公民館南に所在します。見学経路の詳細は現地表示を優先し、農地や私有地には無断で入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"d6af3215-525e-49c8-84c7-ded3a14d44d2","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"22784cb9-41ba-4cf2-9a50-15f14d0ed747","body":"生糸は日本の重要な輸出品となり、群馬の農家、製糸場、商人、研究機関など多くの人々が産業を支えました。富岡製糸場をはじめ、県内各地に絹産業の歴史が残っています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"962bfffe-f2ee-4af0-a3bb-3b5fbdc5f132","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"22c66393-6a84-4ff0-9dc7-5e1cbddd24bc","body":"裾野は長し 赤城山","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"9f1da0c0-f3e4-4b84-a261-938dac68b1fc","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"236ba888-661a-44ff-9126-c3dc87376003","body":"田山花袋は明治から大正期の文学に大きな影響を与えました。自らの経験や現実を見つめる文学表現を追究し、紀行文も数多く残しています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"865acdc4-13bd-4f04-b3b5-2713d5353acc","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"23939452-c118-4444-b89f-5c34164dcaa2","body":null,"role":"picture_card","title":"絵札","alt_text":"碓氷関所跡の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"1cb1876f-c1fb-4f16-9e11-0e6bedf45fe2","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/う-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"23d8d9a0-e6ef-42be-8d2b-534a7a3c6a0b","body":"老農 船津傳次平","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"ccf4aea3-f9f9-49b4-9064-823317e2a571","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"23f78604-5169-4be2-8f3c-4107e3a5a8bd","body":null,"role":"picture_card","title":"絵札","alt_text":"頼政神社・内村鑑三「上州人」碑の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"df0a6c5f-e5da-4538-a7e3-b369d427304c","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/こ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"241b47ce-5fce-459b-9a9d-9c2cc05e4084","body":null,"role":"picture_card","title":"絵札","alt_text":"新島襄旧宅の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"10c77873-d75d-471c-99d4-737f4130c99c","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/へ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"24435f35-563d-4185-9ff3-453f5be65b9e","body":"「ち」は、群馬県民が力を合わせる姿と県人口を表す特別な札です。人口の数字は時代に合わせて改訂され、2024年から「百九十万」となりました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"3aaacece-c523-42a0-978f-e8c609800f0a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"24d0d948-f255-4900-944e-cf195687f9d1","body":"下仁田ねぎは太く、加熱すると甘みが増すことで知られます。こんにゃくも群馬を代表する農産物で、栽培から加工まで地域産業として発展してきました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"c7585385-eb06-4f18-8762-21db4110c156","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"2557b852-2912-4a52-af7c-71eb47ac98e9","body":"古墳周囲には駐車場がありません。高崎市歴史民俗資料館の駐車場を利用し、徒歩約5分で向かうルートが公式に案内されています。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"fb9fc210-467e-42f4-bdf1-e9e7285065bb","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"25837d88-4a5a-4aa1-af95-bbfbb4091b88","body":"境内では本堂だけでなく、全国各地のだるまが集まる達磨堂や、達磨大師立像にも注目してみましょう。だるまの顔や形、願いの込め方を見比べると、単なる土産物ではなく信仰と地域産業が結び付いた文化であることが分かります。境内の洗心亭には、昭和初期に建築家ブルーノ・タウトが暮らしたという別の歴史も重なっています。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.takasaki.gunma.jp/site/sightseeing/4374.html","https://www.city.takasaki.gunma.jp/site/cultural-assets/5358.html","https://www.city.takasaki.gunma.jp/uploaded/attachment/6705.pdf"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"f5d99680-ca79-4b71-98f7-c1a34e8862f9","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":40},{"id":"28b24729-1cdf-4282-8964-d569a11ab631","body":"甘楽町福島に残る古墳で、町の遺跡分布資料では福島1348番地ほかに所在する古墳として記録されています。周辺にも古墳や古代の遺跡が分布する地域です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"b1c51b03-8fa2-434e-a15d-1de4f4543f04","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"2cebd803-0e3f-4a6b-b7d9-a067ae03b2f7","body":"通常見学可能で、13基すべてを巡る散策マップがあります。露出した石室には登らず、崩落防止の柵の内側には入らないでください。駐車場も案内されています。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"23abd7c5-2902-45f1-995a-f581e98cf099","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:53.140508+00:00","display_order":20},{"id":"2d12e738-74cd-488d-9e66-a89eb9d23d3e","body":"心の燈台 内村鑑三","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"df0a6c5f-e5da-4538-a7e3-b369d427304c","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"2d231eb3-fa81-4351-b522-4995296099c7","body":null,"role":"reading_card","title":"読み札","alt_text":"いの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"077359b4-482a-4d66-897f-93e8f6b34153","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/い-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"2d4f54bb-be0c-4ef6-90c5-9375b5b479ef","body":null,"role":"reading_card","title":"読み札","alt_text":"すの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"9f1da0c0-f3e4-4b84-a261-938dac68b1fc","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/す-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"2d7bd980-8978-4ee2-80db-6edcc9526a65","body":"総社古墳群を構成する6世紀後半の前方後円墳。総社古墳群で最後に築造された前方後円墳です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"f1f27490-f754-4c5b-9dce-25923a3ff1f9","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"2e5c0848-5972-4945-9b77-194b6826d42e","body":null,"role":"reading_card","title":"読み札","alt_text":"りの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"cd669926-926a-4794-b11c-73f8b7b09b9e","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/り-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"2e66018d-43cf-4fb4-9493-ebdd0c49ba2b","body":"富岡製糸場では、正門外側からでも世界遺産の工場建築と町並みの関係を感じられます。開場中に入場する場合は、東置繭所や繰糸所などをたどり、繭が生糸になる工程にも注目してみましょう。スタンプ獲得のために入場する必要はありません。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"9e232a01-721f-47df-b253-4a23b86f4312","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"2e9933af-afee-4473-a332-8c9eec103186","body":"遊歩道や展望地点では、川面だけでなく両岸の高さと岩の形を見てみましょう。橋や道路との位置関係も見ると、険しい渓谷を人がどう通り抜けてきたかという視点が加わります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"e92c413a-14c5-46d1-814b-35bd537939f0","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"2f330820-2c90-4a8f-864e-a3ff7d029016","body":null,"role":"reading_card","title":"読み札","alt_text":"ろの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"ccf4aea3-f9f9-49b4-9064-823317e2a571","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ろ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"2f51c734-ebb8-4dc8-ae18-39c03951611c","body":"旧宅では建物の間取りや展示資料を見ながら、世界へ飛び出した人物がどのような家庭・地域とつながっていたかを考えてみましょう。安中の町と同志社へ続く物語の出発点です。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"10c77873-d75d-471c-99d4-737f4130c99c","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"2f9e7597-cbf0-4618-b55b-72a24f223a0d","body":"初版では当時の人口を反映した「百六十万」でした。その後人口の変化に応じて数字が改められてきたため、この札自体が群馬県の人口変化を記録する存在でもあります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"3aaacece-c523-42a0-978f-e8c609800f0a","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"314e049e-aaf8-4a73-b83e-5ec32fc4082a","body":"三波石は庭石としても珍重され、三波石峡は地質と景観の両面で価値を持つ場所です。冬桜は桜山公園などで見られ、晩秋から冬に花を楽しめる独特の景観をつくります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"943686a4-a533-4e8c-bcb5-5a182e10984f","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"318279da-9cc7-45fc-8c10-a367787f1117","body":"記念館周辺では太助に関する資料や伝承を確認し、「実在した商人」と「物語の主人公」の二つの姿を比べてみましょう。沼田城下との関係も意識すると、人物を生んだ地域の背景が見えてきます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"82c45584-ad11-45a5-b30c-0f2f5ebd9716","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"31fe42ed-44e5-430c-b788-21069c99cd52","body":"白石古墳群を構成する県指定史跡。径27.2メートルの円墳または不正八角形墳と考えられ、特徴的な段築と石積みが確認されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"d180cdf0-e8af-4cdc-9ed6-87d91fd0189e","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"327befe1-44f8-4253-b239-173a892abfbd","body":"天狗岩発電所周辺では、水がどこから来てどの高低差を利用しているのかを意識してみましょう。自然エネルギーの展示と実際の設備を結び付けると、「電源群馬」が現代にも続くテーマだと分かります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"cd669926-926a-4794-b11c-73f8b7b09b9e","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"32b18b0f-0eca-4696-a3b1-50553cd5938c","body":"像の前では人物名だけでなく、なぜ農業者が上毛かるたの一札になったのか考えてみましょう。周辺の農地や赤城山麓の景観を見ると、農業改良が人々の生活に直結する仕事だったことが想像できます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"ccf4aea3-f9f9-49b4-9064-823317e2a571","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"340a1f09-2149-490a-8bd2-b7468b622d67","body":null,"role":"reading_card","title":"読み札","alt_text":"めの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"cc638170-bf1a-4342-bada-b6e838686b53","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/め-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"3577fbad-af91-40cf-a423-7da2b0d67d63","body":"江戸幕府は碓氷関所で、特に「入鉄砲」と「出女」を厳しく取り締まりました。東西に門があり、西門は幕府、東門は安中藩が受け持っていました。明治2年（1869年）に廃止され建物は解体されましたが、保存されていた部材を使って東門が復元され、現在も中山道の緊張感を伝えています。周辺の旧中山道や坂本宿と合わせると、峠越えが政治と交通の両面で重要だったことが分かります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.annaka.lg.jp/page/2040.html","https://www.city.annaka.lg.jp/page/21633.html"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"1cb1876f-c1fb-4f16-9e11-0e6bedf45fe2","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":25},{"id":"37edb404-1c48-4961-9f95-36ea6cce006e","body":"国指定史跡として現地見学できます。寺院周辺のため、参拝者や地域の迷惑にならないよう現地の案内と立入範囲に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"9e8a430e-aa4c-4c04-b71f-18fe035c2123","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:11:52.153716+00:00","display_order":20},{"id":"37f269da-a262-4532-9195-012734b4fa45","body":null,"role":"picture_card","title":"絵札","alt_text":"赤城大沼の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"9f1da0c0-f3e4-4b84-a261-938dac68b1fc","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/す-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"3801e52a-a939-405e-9070-a55dcd59b4e6","body":"国指定史跡「総社古墳群」の一部です。前橋市の見学コースでも巡られている史跡です。寺社・個人所有地を含むため、現地の案内や立入範囲を守って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"1244fe03-eb52-40ea-b602-71e85dd8e75b","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"3848a974-e2a2-40d1-a0f6-05e98d61e24b","body":"笹森稲荷神社境内にある県指定史跡で、甘楽町は常時見学可能と案内しています。神社への参拝者に配慮し、立入禁止箇所には入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"b1c51b03-8fa2-434e-a15d-1de4f4543f04","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"3935ba17-8ffd-4605-89c3-fafae22ce26a","body":"「き」は、織物産業で栄えた桐生を詠んでいます。「西の西陣、東の桐生」と称されるほど織物の町として知られ、絹織物の技術と商いが町の発展を支えました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2ab7a19f-8e1f-4f67-9fc6-d087030037e0","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"3971fe76-d95c-400c-986f-f5d5c2df4afa","body":"「し」は、古代の群馬に数多く築かれた古墳と、かつての「毛の国」をしのぶ札です。二子山古墳などの大型古墳は、この地域に強い勢力が存在したことを今に伝えます。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"efa7bd9c-2294-41ee-86ef-b4e06d85accd","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"3b996d30-9bcf-4d3e-940e-d24a19864af7","body":"谷川岳ロープウェイの土合口側から、谷川岳の峰々と谷の深さを眺めてみましょう。ロープウェイが運休している場合でも無理に先へ進まず、登山や積雪の状況に応じて安全を最優先にしてください。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://tanigawadake-joch.com/facilities/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"13e5a60d-c313-459f-ab9c-eedda0fb09d1","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"3ba31dc0-77bd-4ab7-a80c-9875c7994616","body":null,"role":"picture_card","title":"絵札","alt_text":"つつじが岡公園の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"990ef3f1-ee33-4f8e-a1e2-62481553f455","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/は-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"3df82836-2c48-466e-9689-5f00f5172a73","body":null,"role":"reading_card","title":"読み札","alt_text":"まの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"962bfffe-f2ee-4af0-a3bb-3b5fbdc5f132","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ま-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"3e595601-f2ae-4251-9cbb-db7dde21a6e8","body":"5世紀前半に築かれた墳丘長106メートルの帆立貝形古墳。隣接する天神山古墳より少し古いと考えられています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"abc8bf9c-db84-423e-bcb1-26ad18a720cd","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"4023c7ca-186a-4cfc-9e44-cf03ddabd021","body":"上毛野はにわの里公園として整備された史跡です。見学経路を利用して安全に巡れます。八幡塚では墳丘や石棺展示施設も見学できます。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"43fa1879-93fb-4e5e-a089-e4907e659c66","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:09:16.324585+00:00","display_order":20},{"id":"409d9da7-2a49-4d66-8f96-ba4f961d9c96","body":"国指定史跡「総社古墳群」の一部です。前橋市の見学コースでも巡られている史跡です。寺社・個人所有地を含むため、現地の案内や立入範囲を守って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"fe01b7ba-38a3-48df-a3a3-017e371c8052","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"40a9b5d0-85bb-4501-a3ef-b79c5bccf979","body":null,"role":"reading_card","title":"読み札","alt_text":"らの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"2965782c-4ab1-420c-bb73-2a5e89ecc1ae","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ら-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"412576e7-3bbb-4c41-b8d9-55ee99fb3779","body":null,"role":"reading_card","title":"読み札","alt_text":"ふの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"6dfb7057-9b58-4a8e-ae36-62158fceed01","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ふ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"4162a751-8b12-4218-8d41-084d56e8245e","body":null,"role":"picture_card","title":"絵札","alt_text":"草津温泉・湯畑の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"a3f5948a-b9bf-4a34-a9a0-0fd102fa597a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/く-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"42366277-c468-4cae-83c3-953ed555d50b","body":"利根川は農業用水、飲料水、発電、交通、防災など、人々の暮らしと産業を長く支えてきました。一方で洪水との闘いの歴史もあり、治水事業によって流域の姿は大きく変わりました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"58d0874f-2e34-4884-af02-524d77b13b37","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"42687051-a4e5-4936-bdb0-b96d660a1be5","body":"「わ」は、江戸時代の数学「和算」を大きく発展させた関孝和を詠んでいます。代数学的な計算法などを発展させ、日本数学史を代表する人物となりました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2fb9ce0f-ebb8-417b-ae1d-bb2e7eecbed1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"46a17f56-3910-4d00-beac-268788d7d292","body":"中仙道 しのぶ安中杉並木","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"55a8c060-fbb2-4ae0-9f98-b4d01e823641","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"48105e1a-9492-44ba-b162-e84104089e77","body":"「な」は、中山道の安中宿周辺に残る杉並木を詠んでいます。江戸時代の主要街道だった中山道の面影を伝える景観です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"55a8c060-fbb2-4ae0-9f98-b4d01e823641","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"4833df40-6c12-4e53-8d96-44cc4d9a62f8","body":null,"role":"picture_card","title":"絵札","alt_text":"上野國一之宮 貫前神社の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"2432646f-411c-4990-82b4-b311a88c03e7","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ゆ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"487e1abe-e3dc-42e7-9986-2a37f42c51e5","body":null,"role":"picture_card","title":"絵札","alt_text":"多胡碑の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"a8665546-1954-413c-9cb6-174782a88327","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/む-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"490e0c70-8d0f-4c24-b5b4-1d3d5ed26247","body":"現地では碑文の文字をじっくり見てみましょう。読めなくても、文字の配置や石の大きさを観察し、近くのガイダンス施設の解説と照らすと「石そのものが歴史資料」である意味が分かります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"a8665546-1954-413c-9cb6-174782a88327","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"4af0e808-ae48-4c97-a8d1-774d7af05fe2","body":"「ら」は、群馬の雷やからっ風と、人々の義理人情を詠んだ札です。県の解説では、上毛かるた制作時にGHQの検閲で採用できなかった小栗上野介忠順などの偉人への敬意や思いも込められています。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/uploaded/attachment/685268.pdf"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2965782c-4ab1-420c-bb73-2a5e89ecc1ae","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-10-05T13:28:24.213679+00:00","display_order":20},{"id":"4b09ddac-773d-4702-a49b-5d0cf0d9daa2","body":"「ひ」は、高崎観音山に立つ高崎白衣大観音を詠んでいます。巨大な観音像は高崎のランドマークとして市街地からも見ることができます。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"fbfbbed2-218d-483b-a6bf-37b96ec3411d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"4b8e0bdb-b77b-4be8-987d-9b3d01d9c1a9","body":"「む」は、高崎市吉井町に残る多胡碑を詠んでいます。8世紀初めの多胡郡設置を記した石碑で、古代東国の行政や文字文化を伝える貴重な史料です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"a8665546-1954-413c-9cb6-174782a88327","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"4bfcba37-792a-4c12-9beb-02ba16ff77f0","body":null,"role":"reading_card","title":"読み札","alt_text":"きの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"2ab7a19f-8e1f-4f67-9fc6-d087030037e0","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/き-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"4c401890-94a0-4073-826e-36e3c7a537d9","body":"「と」は、関東を代表する大河・利根川を詠んでいます。群馬県内の山地に源を発し、関東平野を流れて太平洋へ注ぐ巨大な水系です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"58d0874f-2e34-4884-af02-524d77b13b37","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"4d4a0569-becf-4e40-becf-ff3ea2d47275","body":"「う」の札は、中山道の要衝だった碓氷関所を詠んでいます。碓氷関所は元和9年（1623年）、江戸幕府によって横川に設置されました。江戸と京都を結ぶ中山道を行き来する人々を監視し、関東の出入口を守る重要な関門でした。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.annaka.lg.jp/page/2040.html","https://www.city.annaka.lg.jp/page/21633.html"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"1cb1876f-c1fb-4f16-9e11-0e6bedf45fe2","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":20},{"id":"4e235747-b6cd-434b-96f1-a6d52ea90cb7","body":"分福茶釜の物語には複数の形がありますが、茂林寺には茶釜にまつわる伝承が残り、狸のイメージとともに親しまれています。寺院の歴史と昔話が重なって地域文化を形成しています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"6dfb7057-9b58-4a8e-ae36-62158fceed01","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"4f6d3b88-2cd6-4fdf-a2cb-d118c576cb28","body":"誇る文豪 田山花袋","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"865acdc4-13bd-4f04-b3b5-2713d5353acc","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"4fb94e4a-07e5-4802-b016-8c5a4e4ec942","body":"現在の温泉街の骨格となる石段街は、天正4年（1576年）頃に形成されたと伝えられています。湯元から温泉を引き、中央の湯樋から左右の屋敷へ湯を分ける仕組みを備えた計画的な温泉街でした。江戸期の湯治場から、明治期の避暑地、そして現在の観光地へ。石段は伊香保が時代ごとに姿を変えながら続いてきた歴史の軸です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.shibukawa.lg.jp/kankou/000357/000359/p000204.html","https://www.city.shibukawa.lg.jp/kankou-site/kankou/000357/000360/p000206.html"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"077359b4-482a-4d66-897f-93e8f6b34153","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":25},{"id":"4fba8c0b-dc43-4d25-ba5b-dc9f53a71e1d","body":null,"role":"reading_card","title":"読み札","alt_text":"への読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"10c77873-d75d-471c-99d4-737f4130c99c","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/へ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"5201bacb-1aac-41b3-b328-63d6c8643268","body":"浅間のいたずら 鬼の押出し","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.tsumagoi-kankou.jp/04-ti-yan-suru-ti-yan-shi-she-1/%E9%AC%BC%E6%8A%BC%E5%87%BA%E3%81%97%E5%9C%92","https://www.tsumagoi-kankou.jp/tsumagoi"]},"is_active":true,"block_type":"text","content_id":"e0aef038-37d9-4dd5-b631-9b16567a68d8","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":10},{"id":"523f2922-198b-4efc-9b41-641ac015acc0","body":null,"role":"reading_card","title":"読み札","alt_text":"この読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"df0a6c5f-e5da-4538-a7e3-b369d427304c","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/こ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"524aec19-d116-44fd-95ce-bd9d4a36735c","body":"登る榛名の キャンプ村","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"3bf0c740-36ec-4a4c-a638-6664221bf83d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"52a462cb-6873-4c70-876a-9ea0fc4ba7e8","body":"榛名山は火山活動で形成された山で、山頂部にはカルデラ湖の榛名湖があります。信仰の山であると同時に、近代以降は観光・レジャーの場としても利用されてきました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"3bf0c740-36ec-4a4c-a638-6664221bf83d","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"534ef5e3-638e-4f80-ae08-851e601bb730","body":"県都前橋 生糸の市","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"source_url":"https://www.city.maebashi.gunma.jp/soshiki/seisaku/kohobrand/gyomu/1_1/2/2680.html"},"is_active":true,"block_type":"text","content_id":"45e0a31d-0919-4f3a-a988-1a0002401d98","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:32:40.55618+00:00","display_order":10},{"id":"53d57d9f-bdab-440f-9bda-a01b93931448","body":null,"role":"picture_card","title":"絵札","alt_text":"尾瀬沼・三平下の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"d7f6c54a-54cd-4716-afef-1823b5b8883a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/せ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"56356ef1-e256-47fb-9610-f1e2a13880a7","body":"上毛野はにわの里公園として整備された史跡です。見学経路を利用して安全に巡れます。八幡塚では墳丘や石棺展示施設も見学できます。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"50f29b73-1714-48ca-aa8a-08de86d0a0fb","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:09:16.324585+00:00","display_order":20},{"id":"56c2b9eb-c0f6-43e4-a582-5ba1d258f5dd","body":null,"role":"reading_card","title":"読み札","alt_text":"くの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"a3f5948a-b9bf-4a34-a9a0-0fd102fa597a","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/く-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"5753c65f-372c-4b9b-a044-36f3782e469b","body":null,"role":"picture_card","title":"絵札","alt_text":"少林山達磨寺の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"f5d99680-ca79-4b71-98f7-c1a34e8862f9","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/え-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"57ccc885-db7d-42b1-bb52-d446bfbfcb24","body":"全国的にも珍しい八角形の古墳。7世紀中葉以後に天皇陵などで採用された形式として知られ、墳丘の稜角が良好に残る貴重な史跡です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"1ed4b917-cc7c-4fb4-a49c-059e9572711a","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"58d2b622-057e-46d1-bedd-2d727cfdf024","body":null,"role":"reading_card","title":"読み札","alt_text":"るの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"c825159c-ceac-4323-953a-ce239e4513fa","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/る-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"59a38a4e-c7f1-425f-a9dc-5c1446535edc","body":"銘仙織り出す 伊勢崎市","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"cc638170-bf1a-4342-bada-b6e838686b53","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"5a928b3d-29e1-4528-a505-8c4092f73608","body":null,"role":"reading_card","title":"読み札","alt_text":"しの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"efa7bd9c-2294-41ee-86ef-b4e06d85accd","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/し-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"5b1e2b8e-acd8-466c-b55f-557d60c7b1e3","body":"三波石と共に 名高い冬桜","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"943686a4-a533-4e8c-bcb5-5a182e10984f","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"5b706741-1487-487f-b96a-e21e87f841d1","body":"6世紀後半に築かれた全長57メートル、高さ4メートルの前方後円墳。墳頂部には諏訪神社が祀られ、凝灰岩の切石を用いた全長5.9メートルの横穴式石室を備えています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"7c30c1f3-aa08-4e2c-9f37-1df1dc1b425c","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"5c8e9076-401b-4630-b468-b278c4587ad3","body":"総社古墳群を構成する7世紀後半の古墳。総社古墳群の終末期を代表する大型古墳です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"fe01b7ba-38a3-48df-a3a3-017e371c8052","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"5d3fe4d4-4050-44fa-b050-d959987f9e47","body":"開花期には花の色だけでなく、株の大きさや枝ぶりにも注目してください。古木と新しい株を見比べると、公園そのものが長い時間をかけて育てられてきたことが分かります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"990ef3f1-ee33-4f8e-a1e2-62481553f455","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"5e21cdfe-f033-49ae-bf05-8ee641f41fc1","body":"「け」の札が表すのは、県庁所在地としての前橋と、近代日本を支えた生糸産業です。前橋では江戸時代から生糸の取引が行われ、1859年の横浜開港後は海外輸出の拡大とともに生糸の集散地として発展しました。1870年には前橋藩が洋式の器械製糸所を設け、前橋は生糸を集める町から、製糸を担う都市へと歩みを進めます。1881年には前橋が正式に群馬県の県庁所在地となりました。「県都」と「生糸の市」という二つの顔を一つの札に刻んだのが、この「け」です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.maebashi.gunma.jp/soshiki/seisaku/kohobrand/gyomu/1_1/2/2680.html","https://www.city.maebashi.gunma.jp/gyosei/8/2/27742.html"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"45e0a31d-0919-4f3a-a988-1a0002401d98","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:32:40.55618+00:00","display_order":20},{"id":"5eb00720-1e41-4521-aba8-7ec5c83612af","body":"街道の並木は旅人の目印や日差し・風を和らげる役割を持ちました。安中から碓氷峠へ向かう道は交通の要衝で、宿場・関所・峠道が一続きの歴史を形成しています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"55a8c060-fbb2-4ae0-9f98-b4d01e823641","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"5f831271-1aac-488e-9dfa-cae41026fa76","body":"1783年の浅間山大噴火は、山麓の暮らしに大きな被害をもたらしました。一方、その噴火の痕跡は現在も鬼押出し園や浅間山熔岩樹型などに残り、嬬恋村は火山と人々の共生を伝える地域になっています。札の「いたずら」という短い言葉の奥には、自然の圧倒的な力と、その土地で暮らしを立て直してきた人々の歴史があります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.tsumagoi-kankou.jp/04-ti-yan-suru-ti-yan-shi-she-1/%E9%AC%BC%E6%8A%BC%E5%87%BA%E3%81%97%E5%9C%92","https://www.tsumagoi-kankou.jp/tsumagoi"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"e0aef038-37d9-4dd5-b631-9b16567a68d8","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":25},{"id":"60983b53-a8b0-4b71-8870-1d4031621326","body":"365段の石段を歩きながら、単なる坂道ではなく「温泉を各宿へ配るためにつくられた町の骨格」として見てみましょう。石段の途中には与謝野晶子の詩が刻まれ、上へ進むと伊香保神社があります。温泉の色や湯の流れ、旅館が石段に沿って並ぶ配置にも注目すると、約400年前の温泉都市計画が現在の街に重なって見えてきます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.shibukawa.lg.jp/kankou/000357/000359/p000204.html","https://www.city.shibukawa.lg.jp/kankou-site/kankou/000357/000360/p000206.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"077359b4-482a-4d66-897f-93e8f6b34153","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":40},{"id":"6137b24e-2d9b-44c3-bc71-7df80ba5638a","body":"滝は吹割 片品渓谷","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"e08b235d-f74c-46ca-baa1-66a760ab4dfb","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"61a42710-33a0-4562-a7f8-1e86a4e9a80e","body":"生品神社では、義貞が挙兵したと伝えられる場所として境内を歩いてみましょう。地図で鎌倉までの距離を確認すると、ここから歴史を動かす軍勢が出発したという物語の大きさを感じられます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"d46c78a7-28a2-4ed5-ac94-7b4f3638d425","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"621b04a1-271f-4b28-acdc-228e54ffc89b","body":"江戸時代の日本では、西洋数学とは別に高度な数学文化が育ちました。関孝和の研究は後世の和算家へ大きな影響を与え、数学を学び競い合う文化の発展につながりました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2fb9ce0f-ebb8-417b-ae1d-bb2e7eecbed1","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"62adef71-1d49-4dfb-a976-38392e5f798e","body":null,"role":"reading_card","title":"読み札","alt_text":"わの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"2fb9ce0f-ebb8-417b-ae1d-bb2e7eecbed1","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/わ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"64e90996-2460-40db-83ba-5ca8c132a719","body":"「そ」は、群馬を代表する民謡の一つ八木節を詠んでいます。軽快なリズムと独特の節回しで知られ、祭りや地域行事で受け継がれてきました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"638afedf-69be-40d0-b926-20185e1f7aa8","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"657a9bf7-7ec0-4e91-8d50-d09d2d2e4a45","body":"「は」は、館林のつつじが岡公園を詠んだ札です。古くからツツジの名所として知られ、多数の古木を含むつつじ群が春の公園を彩ります。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"990ef3f1-ee33-4f8e-a1e2-62481553f455","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"660951f7-4f1c-47bb-b44c-652604192f68","body":"館林のツツジは長い年月にわたって保護・育成され、地域の文化的景観となりました。単なる花壇ではなく、世代を超えて受け継がれてきた植物の歴史を見ることができます。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"990ef3f1-ee33-4f8e-a1e2-62481553f455","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"664405bd-2f26-4395-9f83-bad7e67ac245","body":null,"role":"picture_card","title":"絵札","alt_text":"四万温泉の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"432cd618-9f42-4472-82df-7f3cbe744eac","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/よ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"66704b28-4333-4bba-b01f-d7a78bfdcca4","body":"「て」は、杉木茂左衛門を「義人」としてたたえる札です。重い年貢に苦しむ領民のために訴え出た人物として、みなかみ町月夜野周辺で語り継がれています。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"1f959c33-ef14-4fed-b456-a905ba73c009","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"669e3040-2b43-4683-aae6-e3d4bbcfd79d","body":"つる舞う形の 群馬県","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"abf5e22e-43e5-4ad0-a255-73bde912bb8d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"67290f2a-f789-4e0c-92f7-4bc74c543eae","body":"富岡製糸場ではフランスの技術を取り入れた器械製糸が行われ、各地から集まった工女が技術を学びました。建物群は近代産業の歩みを伝え、「富岡製糸場と絹産業遺産群」として世界遺産に登録されています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"9e232a01-721f-47df-b253-4a23b86f4312","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"679c94f0-7b4d-4b11-b938-778e666f708c","body":"伊香保温泉 日本の名湯","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.shibukawa.lg.jp/kankou/000357/000359/p000204.html","https://www.city.shibukawa.lg.jp/kankou-site/kankou/000357/000360/p000206.html"]},"is_active":true,"block_type":"text","content_id":"077359b4-482a-4d66-897f-93e8f6b34153","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":10},{"id":"683b3b5c-9761-4ca7-95e6-bbc9837fb993","body":"大室公園内で見学できます。園路から安全に巡り、石室見学時は現地の案内に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"4700bb52-6797-4e74-9882-238c1174df77","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"683bd36e-4161-4231-9a40-91d343a79ef4","body":"大室古墳群を構成する6世紀初頭の前方後円墳。墳丘長94メートルで、横穴式石室を備えています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"34991504-f624-49c2-b349-8ac885821944","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"68cc99f5-a7d9-4437-bb30-6c415904abcf","body":"復元整備され一般公開されている県指定史跡です。石室は8時30分から17時まで公開されています。住宅地内なので案内に従い、見学者用スペースからアクセスしてください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"1ed4b917-cc7c-4fb4-a49c-059e9572711a","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"690ef909-2701-44d5-9848-fbdfbfafeab9","body":null,"role":"reading_card","title":"読み札","alt_text":"ねの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"c7585385-eb06-4f18-8762-21db4110c156","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ね-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"69d90b23-bb5b-4798-bd51-ddd3c0ab733d","body":null,"role":"reading_card","title":"読み札","alt_text":"うの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"1cb1876f-c1fb-4f16-9e11-0e6bedf45fe2","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/う-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"69f08063-8c1a-44b1-bbd3-b007466fb2f0","body":"こんにゃくパークでは、こんにゃくの製造工程や歴史を学び、群馬のこんにゃく文化を体験できます。この札では下仁田の名産を詠んでいますが、ここはこんにゃくを体験的に知る代表スポットとして巡ります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.konnyaku-park.com/","https://www.konnyaku-park.com/access/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"c7585385-eb06-4f18-8762-21db4110c156","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"6aa5bde4-cd27-469b-89bc-c9f76106e303","body":null,"role":"picture_card","title":"絵札","alt_text":"こんにゃくパークの絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"c7585385-eb06-4f18-8762-21db4110c156","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ね-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"6ae635b1-0cd6-4582-86fe-245793e94cd9","body":"「つ」は、群馬県の輪郭を舞う鶴の姿に見立てた札です。県民に広く知られた表現で、地図そのものを郷土の象徴に変えています。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"abf5e22e-43e5-4ad0-a255-73bde912bb8d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"6af89017-c51f-468f-b6da-75823f8530fa","body":null,"role":"picture_card","title":"絵札","alt_text":"榛名湖の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"3bf0c740-36ec-4a4c-a638-6664221bf83d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/の-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"6bb77590-7072-4334-b84e-7473127be312","body":null,"role":"reading_card","title":"読み札","alt_text":"のの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"3bf0c740-36ec-4a4c-a638-6664221bf83d","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/の-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"6cfec86b-b2b2-4fec-b83b-a56b1b7aadd0","body":"茂左衛門の物語は、領民のために命をかけた義民伝承として受け継がれてきました。史実と伝承を区別しながら、地域の人々がどのような人物像を大切に伝えてきたかを見ることも重要です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"1f959c33-ef14-4fed-b456-a905ba73c009","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"6d24a188-c762-4061-a3bb-16bb03afd541","body":"繭と生糸は 日本一","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"962bfffe-f2ee-4af0-a3bb-3b5fbdc5f132","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"6f5f5114-b0bd-43d2-b743-69e4c0330ffb","body":null,"role":"picture_card","title":"絵札","alt_text":"船津傳次平像の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"ccf4aea3-f9f9-49b4-9064-823317e2a571","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ろ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"6ff43851-eef5-46cf-bb71-2c4bab14a94c","body":"雷とから風 義理人情","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"2965782c-4ab1-420c-bb73-2a5e89ecc1ae","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"7019c93b-2f32-493d-80dd-0aac43bdf2a1","body":null,"role":"picture_card","title":"絵札","alt_text":"道の駅月夜野矢瀬親水公園の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"58d0874f-2e34-4884-af02-524d77b13b37","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/と-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"708bf3d7-4521-4d8c-99be-b5b2d62fef27","body":"ねぎとこんにゃく 下仁田名産","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"c7585385-eb06-4f18-8762-21db4110c156","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"7218c6e6-7680-43bf-b084-bce457a01191","body":"呑龍上人は江戸時代初期の僧で、困窮する子どもを救ったという伝承から子育て信仰を集めました。金山周辺には金山城跡などもあり、寺院・城・城下の歴史が重なる地域です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"9554c6ed-0b93-45b0-a243-e9120cf67578","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"722180ba-f173-4560-af8f-33fe547f84d6","body":"四万温泉の温泉街を歩き、湯の流れや共同浴場、飲泉所など温泉文化に注目してみましょう。塩之湯飲泉所は温泉街中ほどの散策地点で、「世のちり洗う」と詠まれた湯治場の空気を感じる起点になります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://nakanojo-kanko.jp/shima/hotsprings/%E5%A1%A9%E4%B9%8B%E6%B9%AF%E9%A3%B2%E6%B3%89%E6%89%80/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"432cd618-9f42-4472-82df-7f3cbe744eac","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"73347ced-f163-4593-9deb-ead44d23f8f8","body":"分福茶釜の 茂林寺","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"6dfb7057-9b58-4a8e-ae36-62158fceed01","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"75466648-2ce5-4ca2-af19-0775709330bc","body":"日本で最初の 富岡製糸","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"9e232a01-721f-47df-b253-4a23b86f4312","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"75bcb641-9108-4029-8e99-4513f1990d2d","body":null,"role":"picture_card","title":"絵札","alt_text":"鬼押出し園の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"e0aef038-37d9-4dd5-b631-9b16567a68d8","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/あ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"77269bcb-7ba7-49fb-b8f2-bc235039f8c8","body":"参道や境内に並ぶ狸像を眺めながら、どこから物語の世界が始まるのか探してみましょう。寺の由緒と昔話を分けて確認すると、伝承が観光や地域イメージへ広がった過程も楽しめます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"6dfb7057-9b58-4a8e-ae36-62158fceed01","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"7742bc10-f457-4a5c-923f-d8db967943e4","body":"4世紀に築かれたと推定される竪穴式の円墳。発掘時には鏡など多くの出土品が見つかり、肥沃な地域を治めた有力者の墓と考えられています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"9d6d7430-036a-4ed8-83a6-15ea8e8d6b64","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"77b594f4-3c22-4a01-8ce9-01ac180f5d00","body":"見学自由で駐車場があります。ガイダンス施設も整備されています。史跡内では案内表示に従い、保護された区域や石室への立入制限を守って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"85e33022-6474-4ec5-a14d-ce2a026af545","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:53.140508+00:00","display_order":20},{"id":"78f13f48-fa97-4f12-99d4-9b591abeb43c","body":"和算の大家 関孝和","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"2fb9ce0f-ebb8-417b-ae1d-bb2e7eecbed1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"7b713c33-cd7d-4faf-a560-039c9fa68021","body":"「か」は、関東と信越を結ぶ交通の要衝、高崎を詠んでいます。古くは中山道の宿場、近代以降は鉄道の結節点として発展し、現在も新幹線や在来線、高速道路が交わります。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"56c86827-bb9f-484e-b4a2-36b70aa2b2f1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"7be5dd04-ad72-4ed5-b6e4-1dd9a96633d4","body":"尾瀬はダム開発計画や観光による環境負荷をめぐる歴史の中で、自然保護運動の象徴的な場所となりました。木道や利用ルールも、美しい湿原を次世代へ残すための仕組みです。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"d7f6c54a-54cd-4716-afef-1823b5b8883a","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"7c25db48-74a7-4eb7-94d5-81fa4b9cb683","body":"6世紀後半の全長52メートルの前方後円墳。横穴式石室から新羅の古墳出土品に似た金銅製冠が出土し、朝鮮半島との文化交流を伝える重要な古墳です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"b4399e92-9e9d-4a37-94ae-2fd36f9b54ad","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"7d47035c-63ad-4ae6-a688-519c51342ebc","body":"湯畑では大量の温泉が流れる様子と、周囲に宿や店が集まる町の構造を見てみましょう。西の河原や共同浴場などへ歩くと、温泉が観光資源であるだけでなく地域文化そのものだと分かります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"a3f5948a-b9bf-4a34-a9a0-0fd102fa597a","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"7d541b17-fa6b-4259-a1bd-d4d3bdf68bec","body":"多胡碑は山上碑・金井沢碑とともに「上野三碑」と呼ばれています。石に刻まれた文字が千年以上残り、古代の制度、人名、地域社会を現在へ直接伝えています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"a8665546-1954-413c-9cb6-174782a88327","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"7ea500ce-b224-43e2-b6b5-729c813e63f7","body":"沼田城下の 塩原太助","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"82c45584-ad11-45a5-b30c-0f2f5ebd9716","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"7eaac22d-94b5-4741-9323-58132585bbc7","body":null,"role":"picture_card","title":"絵札","alt_text":"大光院（呑龍様）の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"9554c6ed-0b93-45b0-a243-e9120cf67578","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/お-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"7ebd58c3-ac9f-4072-8e2c-f7fa256d557b","body":"4世紀中頃に築かれた全長130メートルの前方後方墳。全国的にも数少ない形式で最大級の規模をもち、周堀を含めると南北約180メートルに及びます。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"ee712e4b-53b9-45b9-a690-370843e337be","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"7f51106f-7d99-413d-b475-8667644da918","body":"園内では、まず黒々とした溶岩の形と、その向こうに見える浅間山の位置関係を見てみましょう。溶岩の間には高山植物も育ち、噴火後の土地に自然が戻っていく様子も観察できます。さらに嬬恋村内の浅間山熔岩樹型や鎌原観音堂まで足を延ばすと、1783年の噴火を「地形」と「人の記憶」の両方からたどれます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.tsumagoi-kankou.jp/04-ti-yan-suru-ti-yan-shi-she-1/%E9%AC%BC%E6%8A%BC%E5%87%BA%E3%81%97%E5%9C%92","https://www.tsumagoi-kankou.jp/tsumagoi"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"e0aef038-37d9-4dd5-b631-9b16567a68d8","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":40},{"id":"7f63032e-60f6-4e42-878a-973f4736b1ee","body":null,"role":"reading_card","title":"読み札","alt_text":"かの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"56c86827-bb9f-484e-b4a2-36b70aa2b2f1","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/か-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"81457ae5-d9d7-4837-b4f5-a20e8c5785eb","body":"小栗上野介忠順は江戸から権田村へ移り、東善寺を仮住まいとしました。東善寺の境内には小栗父子と家臣らの供養墓、裏山には小栗上野介忠順の本墓があります。「ら」の札に込められた偉人への敬意をたどる場所として、このアプリでは東善寺を訪問先に選んでいます。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.takasaki.gunma.jp/site/sightseeing/78704.html","https://www.pref.gunma.jp/uploaded/attachment/685268.pdf"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2965782c-4ab1-420c-bb73-2a5e89ecc1ae","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-10-05T13:28:24.213679+00:00","display_order":25},{"id":"8219cc2f-05f8-44c9-9d81-85f1c9aee1cc","body":"観音塚考古資料館のすぐ北側にあり、横穴式石室の中も見学できます。資料館には駐車場があります。現地の案内に従って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"c9052369-f319-4885-beb5-9346f2d6c46f","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"823238cb-5510-43a0-ae18-40115b4ca1ed","body":null,"role":"reading_card","title":"読み札","alt_text":"はの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"990ef3f1-ee33-4f8e-a1e2-62481553f455","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/は-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"833d8d15-6a71-40d1-b755-edff709a91ea","body":"山上碑と一体で国の特別史跡に指定されている古墳。山上碑は681年に建てられ、古墳と石碑を通して古代上野の社会や人々のつながりをたどれる貴重な史跡です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"37174a4c-e9e1-4b83-8dda-458f027c1246","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"83453b1a-0746-4f10-9be6-92d5aff2ceaf","body":"吹割の滝周辺では、長い時間をかけた川の侵食が岩盤を削り、現在の渓谷地形をつくりました。自然の造形そのものが地域を代表する観光資源になっています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"e08b235d-f74c-46ca-baa1-66a760ab4dfb","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"834ac776-3cb4-43ae-ab11-d5ea686602f1","body":null,"role":"reading_card","title":"読み札","alt_text":"よの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"432cd618-9f42-4472-82df-7f3cbe744eac","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/よ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"85bd9e16-412b-4654-a87d-56d5d6a0127e","body":null,"role":"reading_card","title":"読み札","alt_text":"なの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"55a8c060-fbb2-4ae0-9f98-b4d01e823641","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/な-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"87976ebe-8de6-460c-b0c0-2cb93f9bcb4d","body":"大室古墳群を構成する6世紀前半の前方後円墳。墳丘長111メートルで、大室古墳群の大型古墳を比較しながら巡れる代表的な一基です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"4700bb52-6797-4e74-9882-238c1174df77","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"886d0dcc-3fbb-415d-8978-2e1f170ec603","body":"さちの池は、鶴舞う形の群馬県をかたどって造られた池です。池の輪郭を実際の県土と重ねながら眺めると、「つる舞う形」という札の表現を現地で確かめられます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.maebashi.gunma.jp/kurashi_tetsuzuki/4/1/12/1/13832.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"abf5e22e-43e5-4ad0-a255-73bde912bb8d","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"89e1ae26-ddef-40ea-a11f-379edfede037","body":"赤城山は火山活動によって形づくられ、人々の信仰や農業、観光とも深く関わってきました。山頂部の大沼や覚満淵など、多様な自然環境も魅力です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"9f1da0c0-f3e4-4b84-a261-938dac68b1fc","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"8adaaa24-b6cf-4b64-a78b-5eaf155b8dc1","body":null,"role":"picture_card","title":"絵札","alt_text":"妙義神社の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"f775a89b-f08f-431f-986c-dbf4152db415","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/も-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"8b171504-069a-4196-b35c-8b4aecceb30d","body":"「ぬ」は、沼田地域にゆかりを持つ塩原太助を詠んでいます。江戸で成功した商人として知られ、勤勉・孝行・義理人情を象徴する人物として講談などで広く語られました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"82c45584-ad11-45a5-b30c-0f2f5ebd9716","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"8b287af8-dd63-46eb-a576-8b556b7635c1","body":"大室公園内で見学できます。園路から安全に巡り、石室見学時は現地の案内に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"34991504-f624-49c2-b349-8ac885821944","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"8b3a5f69-e7cf-49ac-b87b-98f83a9cbf26","body":"前橋市指定史跡で、朝倉・広瀬地区の文化財として案内されています。住宅地に近いため、公道や見学可能な範囲から見学し、周辺の私有地には立ち入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"b4399e92-9e9d-4a37-94ae-2fd36f9b54ad","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"8bdc957a-1fed-42a7-ab0b-1f8c1a928bef","body":null,"role":"reading_card","title":"読み札","alt_text":"さの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"943686a4-a533-4e8c-bcb5-5a182e10984f","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/さ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"8c5bbff6-6a73-4352-a60c-c5c0da4a0078","body":"赤城大沼の湖畔からは、山頂だけでなく赤城山の大きな山体と周囲の地形を意識してみましょう。大沼周辺の高地の自然とあわせて、長い裾野を持つ赤城山のスケールを感じられます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3789.html"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"9f1da0c0-f3e4-4b84-a261-938dac68b1fc","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"8c87c188-8fa9-43ff-8d51-56b2bad5a72a","body":"石室以外はいつでも自由に見学できます。石室には見学時間があり、個人見学は現地の解説員へ申し出てください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"7fc13c95-ddd0-4c5a-aa67-cb899077a496","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:09:16.324585+00:00","display_order":20},{"id":"8ce28403-c736-45c2-a9cb-51c8e5a1bafb","body":null,"role":"picture_card","title":"絵札","alt_text":"群馬県立日本絹の里の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"962bfffe-f2ee-4af0-a3bb-3b5fbdc5f132","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ま-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"8da09e66-cb6a-4b24-b3f4-f45c0448fabe","body":"昔を語る 多胡の古碑","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"a8665546-1954-413c-9cb6-174782a88327","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"8e9a20b4-289c-4655-b9df-719aeca05ca8","body":"5世紀後半から6世紀初めの保渡田古墳群を構成する約100メートルの前方後円墳。復元整備された墳丘では、54体の人物・動物埴輪を配置した形象埴輪配列区や石棺展示施設を見学できます。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"43fa1879-93fb-4e5e-a089-e4907e659c66","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"8f0ed8bf-d80a-4d59-97e2-c8e12fea8395","body":null,"role":"reading_card","title":"読み札","alt_text":"たの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"e08b235d-f74c-46ca-baa1-66a760ab4dfb","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/た-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"9005e863-4453-4388-9553-f2baf52e3cf6","body":null,"role":"picture_card","title":"絵札","alt_text":"吉岡自然エネルギーパークの絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"cd669926-926a-4794-b11c-73f8b7b09b9e","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/り-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"9052b749-8332-4aaf-97ef-bac68cbc14e7","body":"群馬県は東日本有数の古墳県で、古墳や埴輪から古代の政治・社会・交流を読み取ることができます。「毛の国」は後に上野国・下野国へ分かれ、上野国が現在の群馬県につながります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"efa7bd9c-2294-41ee-86ef-b4e06d85accd","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"91e3f5d2-b53e-42a3-97e5-74b91b95c634","body":"船津傳次平は農業の現場で培った知識をもとに、明治政府の農業政策にも関わりました。近代農学が導入される時代に、在来の農業技術と新しい知識をつなぐ役割を果たした人物です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"ccf4aea3-f9f9-49b4-9064-823317e2a571","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"91ec52e0-2799-4f03-842c-33761a59b7b7","body":"天下の義人 茂左衛門","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"1f959c33-ef14-4fed-b456-a905ba73c009","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"92ae8ef6-e9ce-4ed0-8bd1-dbd0fd90df52","body":"群馬県立歴史博物館では、群馬の歴史を時代を追って見渡せます。「力あわせる百九十万」という札を、人口の数字だけでなく、県内各地で積み重なった人々の暮らしと歴史から考えてみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://grekisi.pref.gunma.jp/information/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"3aaacece-c523-42a0-978f-e8c609800f0a","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"9397ed04-db9f-4b5d-9cd5-342373a629b1","body":"「や」は、吾妻川が刻んだ吾妻峡の渓谷美を詠んでいます。奇岩、断崖、清流、紅葉などが組み合わさる群馬を代表する景勝地の一つです。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"e92c413a-14c5-46d1-814b-35bd537939f0","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"93a95473-8626-4130-8051-8b2a57e17602","body":"矢瀬親水公園では、利根川上流の流れと周辺の地形を観察してみましょう。山地から水を集めて関東平野へ向かう大河の上流域に立つことで、「坂東一の川」という札のスケールを感じられます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.enjoy-minakami.jp/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"58d0874f-2e34-4884-af02-524d77b13b37","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"941d91c7-8b13-49a3-994f-dcf3833f2702","body":"朝倉・広瀬古墳群の史跡です。前橋市の史跡案内に従い、公道や見学可能な範囲から見学してください。周辺住宅や私有地には立ち入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"c34573c8-110d-488d-83c7-db21a9663e02","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:11:52.153716+00:00","display_order":20},{"id":"94e9a042-dbdf-4198-b1a0-cc3780aa9117","body":null,"role":"reading_card","title":"読み札","alt_text":"みの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"13e5a60d-c313-459f-ab9c-eedda0fb09d1","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/み-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"95219769-24dd-4b5a-973c-846db8c00bee","body":"碓氷峠の 関所跡","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.annaka.lg.jp/page/2040.html","https://www.city.annaka.lg.jp/page/21633.html"]},"is_active":true,"block_type":"text","content_id":"1cb1876f-c1fb-4f16-9e11-0e6bedf45fe2","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":10},{"id":"95923455-35c5-4724-a89f-3038c7be77c6","body":"4世紀中頃に築かれた東国最古級の大型前方後円墳。もとは全長129メートルで、三角縁神獣鏡をはじめ15種165点の副葬品が発見され、国の重要文化財に指定されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"c34573c8-110d-488d-83c7-db21a9663e02","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"972793d2-fb61-45c2-9aca-4eac2762bd2b","body":"6世紀後半に造られた全長97メートルの前方後円墳。発掘調査では多数の埴輪や豊富な副葬品が確認されました。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"7fc13c95-ddd0-4c5a-aa67-cb899077a496","created_at":"2026-09-24T14:56:26.857973+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"97802f7e-f36a-41f5-ba42-7e96dafc308b","body":"「る」は、上越国境を越える鉄道の難所、清水トンネルとループ線を詠んでいます。急勾配を克服するための鉄道技術が山岳交通を大きく変えました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"c825159c-ceac-4323-953a-ce239e4513fa","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"97b6dcf6-6c27-4d77-a108-5818168395b4","body":null,"role":"reading_card","title":"読み札","alt_text":"けの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"45e0a31d-0919-4f3a-a988-1a0002401d98","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/け-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"97c00bbd-952f-440d-acbe-abfa53117389","body":"6世紀前半に築かれた長さ22.5メートルの帆立貝形古墳。多数の形象埴輪が出土し、現在は古墳公園として復元整備されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"298a8d36-b28c-4028-9d53-f4b9bcc6dfaf","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"98a0e7bb-012b-4da4-8b73-32f2c35f2b6c","body":"5世紀末から6世紀初頭に築かれた帆立貝式古墳。全国的にも珍しい四重の埋葬施設が確認され、神獣鏡や大刀、馬具などが出土しました。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"d6af3215-525e-49c8-84c7-ded3a14d44d2","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"9987c04f-e345-47d1-99ff-559cc252ba75","body":"白石古墳群を構成する5世紀前半の大型前方後円墳。全長約140メートルで、刀・銅鏡・勾玉・石製模造品などが出土しています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"2b22c5ce-37a6-4a7e-8c0b-354945bd081f","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"99e621f8-6d8b-46a1-903f-acd836b14d33","body":"毛野国白石丘陵公園の史跡エリアです。整備された見学経路を利用し、史跡保護のため立入制限や現地表示に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"d180cdf0-e8af-4cdc-9ed6-87d91fd0189e","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"9b561065-82ef-4aff-9ad5-bbea6c6ba455","body":"玉村町が史跡・歴史散策スポットとして案内している古墳です。所在地は角渕4755-1・2。周囲は田園地帯のため農地には入らず、案内のある側から見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"9d6d7430-036a-4ed8-83a6-15ea8e8d6b64","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"9bf028ba-06cb-46f0-9a0b-08bdd40ad99d","body":"「あ」の札は、浅間山の噴火が生み出した鬼押出しの景観を詠んでいます。鬼押出し園に広がる溶岩は、天明3年（1783年）の浅間山大噴火によるものです。巨大な溶岩の原と浅間山を目の前にすると、火山活動が土地の姿そのものをつくってきたことを実感できます。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.tsumagoi-kankou.jp/04-ti-yan-suru-ti-yan-shi-she-1/%E9%AC%BC%E6%8A%BC%E5%87%BA%E3%81%97%E5%9C%92","https://www.tsumagoi-kankou.jp/tsumagoi"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"e0aef038-37d9-4dd5-b631-9b16567a68d8","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":20},{"id":"9bf037d6-6165-4d1d-9ae3-c1fc53b9bf11","body":"6世紀前半につくられた三段築成の前方後円墳。全長150メートルで、6世紀代の古墳として東日本最大級。大型円筒埴輪や人物・馬などの形象埴輪が出土しています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"a40bfeb6-0df2-4bb4-a0ad-9850c5b828b4","created_at":"2026-09-24T14:56:26.857973+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"9bf990d3-5a2a-4045-963b-f00e2e74580f","body":"「も」は、奇岩・岩峰が連なる妙義山と紅葉の景観を詠んでいます。上毛三山の一つで、独特の険しい山容が大きな特徴です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"f775a89b-f08f-431f-986c-dbf4152db415","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"9cb478aa-1845-45ef-bf43-0597b2e1d161","body":null,"role":"picture_card","title":"絵札","alt_text":"木崎宿・色地蔵の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"638afedf-69be-40d0-b926-20185e1f7aa8","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/そ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"9e4a4033-6479-4f03-aa19-51db8a464ba1","body":"「に」は、明治政府が設立した官営富岡製糸場を詠んでいます。1872年に操業を開始し、日本の近代製糸技術の普及と生糸の品質向上に大きな役割を果たしました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"9e232a01-721f-47df-b253-4a23b86f4312","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"9ed90203-54e3-4407-a903-28089204d53f","body":"近代化とともに電力需要が増えると、利根川水系などで水力発電が発達しました。発電所やダムは地域の産業だけでなく、首都圏を含む広い地域の暮らしを支えるインフラとなりました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"cd669926-926a-4794-b11c-73f8b7b09b9e","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"9f225e21-4bd8-45c6-a8bf-a0d566839ab2","body":"大室公園内で見学できます。園路から安全に巡り、石室見学時は現地の案内に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"de8cdf05-ccb5-478f-8a62-f96ba8393d47","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"9f3cf7c4-2d11-43e2-b083-56a885e23f7b","body":"耶馬溪しのぐ 吾妻峡","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"e92c413a-14c5-46d1-814b-35bd537939f0","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"9f4302eb-ae3e-499a-b1ee-84f272818e19","body":"「ま」は、群馬を支えた養蚕・製糸産業を詠んでいます。山間部から平野部まで養蚕が広がり、繭と生糸は近代群馬を代表する産業となりました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"962bfffe-f2ee-4af0-a3bb-3b5fbdc5f132","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"9fc78c28-cfd5-4e61-84d7-d5a6e6fccd19","body":"高崎駅では路線図や新幹線・在来線の分岐を見てみましょう。駅周辺から旧中山道方面へ歩くと、現代の巨大な交通拠点と宿場町だった時代を重ねて見ることができます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"56c86827-bb9f-484e-b4a2-36b70aa2b2f1","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"a01935b9-0885-43b5-9212-34582726f262","body":null,"role":"reading_card","title":"読み札","alt_text":"つの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"abf5e22e-43e5-4ad0-a255-73bde912bb8d","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/つ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"a21f1daa-27c6-4cee-8cb6-8d6c75cca972","body":null,"role":"picture_card","title":"絵札","alt_text":"上毛かるた「雷と空風 義理人情」の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"2965782c-4ab1-420c-bb73-2a5e89ecc1ae","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ら-絵札.jpg","updated_at":"2026-10-05T13:28:24.213679+00:00","display_order":30},{"id":"a3ca3493-68c5-4927-9c92-1c1e07a3be9c","body":null,"role":"reading_card","title":"読み札","alt_text":"ぬの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"82c45584-ad11-45a5-b30c-0f2f5ebd9716","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ぬ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"a3d3eec0-de2d-4f01-965a-7799369a7623","body":"頼政神社の境内には、内村鑑三の漢詩「上州人」を刻んだ記念碑があります。碑文を読み、内村が幼少期を過ごした高崎と、その思想につながる郷土意識を感じてみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.takasaki.gunma.jp/site/cultural-assets/6555.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"df0a6c5f-e5da-4538-a7e3-b369d427304c","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"a4bf42db-a1bc-4dc7-bb5c-93fee5830c42","body":null,"role":"reading_card","title":"読み札","alt_text":"その読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"638afedf-69be-40d0-b926-20185e1f7aa8","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/そ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"a4f984d7-2fdd-4c72-9cbc-e7c40fcdcb8d","body":null,"role":"picture_card","title":"絵札","alt_text":"保渡田古墳群・井出二子山古墳の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"efa7bd9c-2294-41ee-86ef-b4e06d85accd","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/し-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"a4fbd504-f406-485c-8b15-63c89c0bde20","body":null,"role":"reading_card","title":"読み札","alt_text":"むの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"a8665546-1954-413c-9cb6-174782a88327","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/む-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"a70e4b47-6ad5-4ce7-9936-a38d26c8782d","body":"上越国境の急峻な山々と豪雪は交通の難所を生む一方、登山・スキー・温泉などの観光資源にもなりました。自然条件の厳しさと魅力が表裏一体になった地域です。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"13e5a60d-c313-459f-ab9c-eedda0fb09d1","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"a7564546-5d09-4ddb-9fe1-a63b733756d3","body":"大室公園内で見学できます。園路から安全に巡り、石室見学時は現地の案内に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"68a99045-372f-4553-9c5e-eefa22d03a62","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"a75c1bfd-d29f-4e4d-9497-4388f2706a5b","body":null,"role":"picture_card","title":"絵札","alt_text":"谷川岳ロープウェイの絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"13e5a60d-c313-459f-ab9c-eedda0fb09d1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/み-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"a7a43d28-97f2-4631-81a2-72ec8ffdbc86","body":null,"role":"reading_card","title":"読み札","alt_text":"ひの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"fbfbbed2-218d-483b-a6bf-37b96ec3411d","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ひ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"a7f8c1a3-4299-4481-b2cb-cab8a502ec58","body":"縁起だるまの 少林山","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.takasaki.gunma.jp/site/sightseeing/4374.html","https://www.city.takasaki.gunma.jp/site/cultural-assets/5358.html","https://www.city.takasaki.gunma.jp/uploaded/attachment/6705.pdf"]},"is_active":true,"block_type":"text","content_id":"f5d99680-ca79-4b71-98f7-c1a34e8862f9","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":10},{"id":"a86554f2-7151-4251-9100-f14ffb6d998f","body":"6世紀後半に築かれた直径24メートル、高さ4メートルの二段築成の円墳。装飾大刀をはじめとする副葬品や埴輪が出土し、一括して国の重要文化財に指定されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"8f1142c5-6241-4cbb-af16-e1ca85a76b73","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"a95ea716-429a-41b8-bbce-ad6636f79cc6","body":"総社古墳群を構成する7世紀中葉から後半の古墳。古代上野国の政治・文化の中心地域に残る大型古墳です。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"25f6080f-6de6-4a0d-851d-d9a2d478e270","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"aad96102-3985-43c3-83f0-bf48db229bb9","body":"伊勢崎では養蚕・製糸と結び付いた織物産業が発達し、銘仙は全国へ流通しました。デザインや生産技術の工夫によって、地域産業が都市の発展を支えました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"cc638170-bf1a-4342-bada-b6e838686b53","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"ab29fe64-2c71-4461-928b-5858fc625bb1","body":null,"role":"reading_card","title":"読み札","alt_text":"ちの読み札","link_url":null,"metadata":{"aspect_ratio":0.7917570498915402},"is_active":true,"block_type":"image","content_id":"3aaacece-c523-42a0-978f-e8c609800f0a","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ち-読み札.png","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"ab2fc04b-4b2d-4af8-8c93-fec67cc9681f","body":null,"role":"picture_card","title":"絵札","alt_text":"いせさき明治館の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"cc638170-bf1a-4342-bada-b6e838686b53","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/め-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"ab4de067-e44a-45bb-a417-3365807fca88","body":null,"role":"reading_card","title":"読み札","alt_text":"ゆの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"2432646f-411c-4990-82b4-b311a88c03e7","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/ゆ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"ab93d150-5a7d-4e20-b5c5-c2a66a614e4a","body":"国指定史跡「総社古墳群」の一部です。前橋市の見学コースでも巡られている史跡です。寺社・個人所有地を含むため、現地の案内や立入範囲を守って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"f1f27490-f754-4c5b-9dce-25923a3ff1f9","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"ada1bf81-6068-47d4-ae37-888e5687d66c","body":null,"role":"reading_card","title":"読み札","alt_text":"あの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"e0aef038-37d9-4dd5-b631-9b16567a68d8","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/あ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"ae178419-15b7-46ce-9890-b3388baaf419","body":"保渡田古墳群の一基で、西光寺境内と重なる史跡です。寺院への参拝者や墓地利用者に十分配慮し、境内の案内と立入範囲に従って見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"b3d85f5e-c4a2-40d7-a6f4-61f4a339033b","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:12:57.215924+00:00","display_order":20},{"id":"aed22c54-3460-4f5e-b9b5-d875022d3d33","body":null,"role":"picture_card","title":"絵札","alt_text":"吾妻峡の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"e92c413a-14c5-46d1-814b-35bd537939f0","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/や-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"aed776a6-dee5-48c8-994c-718bafd6e93b","body":null,"role":"picture_card","title":"絵札","alt_text":"高崎白衣大観音の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"fbfbbed2-218d-483b-a6bf-37b96ec3411d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ひ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"af48f51a-2165-4f98-887d-0f142dd872fe","body":"「お」は、太田の金山と大光院の呑龍上人を詠んだ札です。大光院は「子育て呑龍さま」の名で親しまれ、太田を代表する寺院の一つです。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"9554c6ed-0b93-45b0-a243-e9120cf67578","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"affe1c68-7c25-4fc7-992d-6aa3dd448210","body":"毛野国白石丘陵公園の史跡エリアです。整備された見学経路を利用し、史跡保護のため立入制限や現地表示に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"8f1142c5-6241-4cbb-af16-e1ca85a76b73","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"b00bf635-4622-4834-a6e0-25e146c23728","body":"上越線の建設では険しい地形と豪雪が大きな課題でした。長大トンネルとループ線の完成によって群馬と新潟の鉄道交通が改善し、人や物の移動が大きく変化しました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"c825159c-ceac-4323-953a-ce239e4513fa","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"b1811510-d78a-4775-b3e3-9c37af318ae5","body":"朝倉・広瀬古墳群の史跡です。前橋市の史跡案内に従い、公道や見学可能な範囲から見学してください。周辺住宅や私有地には立ち入らないでください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"ee712e4b-53b9-45b9-a690-370843e337be","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:11:52.153716+00:00","display_order":20},{"id":"b1bd2892-7266-4ca5-9ba3-64a1c2ede085","body":"歴史に名高い 新田義貞","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"d46c78a7-28a2-4ed5-ac94-7b4f3638d425","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"b27bcdc6-a760-43a2-86e0-bd8bf8414186","body":"「よ」は、山あいの静かな温泉地・四万温泉を詠んでいます。古くから湯治場として知られ、清流と温泉街が一体となった景観を持ちます。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"432cd618-9f42-4472-82df-7f3cbe744eac","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"b43eeb37-48a4-4df5-9743-d1d68a125d6d","body":"そろいの仕度で 八木節音頭","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"638afedf-69be-40d0-b926-20185e1f7aa8","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"b6bb0251-d957-4019-a407-efb2fca2b7e8","body":"「こ」は、近代日本を代表する思想家・キリスト教思想家の内村鑑三を詠んだ札です。内村は高崎藩士の家に生まれ、宗教・社会・教育について多くの著作を残しました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"df0a6c5f-e5da-4538-a7e3-b369d427304c","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"b893b7b0-e91b-4e7c-adb5-98f03af56c45","body":"桐生では長い年月をかけて織物の技術、工場、商家、町並みが形成されました。近代化の中でも織物産業は重要な役割を担い、現在もノコギリ屋根工場などに産業都市の面影が残ります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2ab7a19f-8e1f-4f67-9fc6-d087030037e0","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"b8a008b3-5d86-4d5a-9ad1-99aed5b88a7d","body":"桜山公園の第1の広場では、約1,500トンの三波石を使った日本庭園と、季節には冬桜を同じ公園内で楽しめます。「三波石」と「冬桜」という札の二つの主役を一地点で観察してみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.fujioka.gunma.jp/kanko_bunka_sports/kankojoho/3/2/3151.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"943686a4-a533-4e8c-bcb5-5a182e10984f","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"b8e96cb3-4b12-4433-ae46-a101d51aed55","body":"八木節は人々が集まる場で演奏され、唄・笛・太鼓・鉦などが一体となって場を盛り上げます。桐生八木節まつりなどを通じ、現在も「見る文化」ではなく参加する文化として生きています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"638afedf-69be-40d0-b926-20185e1f7aa8","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"badbd0a4-593b-41dc-b4b8-cb5991d8d14f","body":"白衣観音 慈悲の御手","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"fbfbbed2-218d-483b-a6bf-37b96ec3411d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"baec71c5-a19e-4cc0-b77f-9f089ac89655","body":"「み」は、みなかみと谷川岳の山岳観光を詠んでいます。谷川岳は登山の名所であり、周辺は積雪を生かしたスキーなど冬のレジャーでも知られます。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"13e5a60d-c313-459f-ab9c-eedda0fb09d1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"bb971a16-7b0b-47e6-a6c6-3ea28c7a9add","body":null,"role":"picture_card","title":"絵札","alt_text":"富岡製糸場の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"9e232a01-721f-47df-b253-4a23b86f4312","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/に-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"bbec2051-4da6-4127-957c-3a0c348d07e0","body":"毛野国白石丘陵公園の史跡エリアです。整備された見学経路を利用し、史跡保護のため立入制限や現地表示に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"2b22c5ce-37a6-4a7e-8c0b-354945bd081f","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:08:12.908738+00:00","display_order":20},{"id":"bbed7056-a760-4c21-99cc-d22c1e608459","body":"大光院では本堂や境内を歩き、「子育て呑龍」の信仰が今も続いていることに注目しましょう。時間があれば金山城跡方面にも足を延ばすと、札にある「太田金山」の地形と歴史を一緒にたどれます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"9554c6ed-0b93-45b0-a243-e9120cf67578","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"bcd840f7-25da-441d-851f-e81742df0de6","body":"4世紀前半に築かれたと推定される全長95メートルの前方後方墳。県内最古級の古墳の一つで、前方部頂上には島名神社が鎮座し、周濠から底部穿孔壺形土器が出土しています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"fb9fc210-467e-42f4-bdf1-e9e7285065bb","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"bceaae60-1fd3-46a7-8ff0-b53c7a3d9f83","body":"桐生は 日本の機どころ","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"2ab7a19f-8e1f-4f67-9fc6-d087030037e0","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"bdcb5795-0326-491d-a733-984f353c1e12","body":"沼田市奈良町に残る7世紀の群集墳。現在13基が確認され、横穴式石室や馬具の副葬から、古代上野における馬生産の広がりを伝えます。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"23abd7c5-2902-45f1-995a-f581e98cf099","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"be00d6f6-2b13-43e5-b5a3-e5bb0f35fe56","body":null,"role":"reading_card","title":"読み札","alt_text":"えの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"f5d99680-ca79-4b71-98f7-c1a34e8862f9","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/え-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"bfa24e2f-662c-4cb7-9c59-5711b58400f5","body":null,"role":"reading_card","title":"読み札","alt_text":"との読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"58d0874f-2e34-4884-af02-524d77b13b37","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/と-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"c05e7b6c-a459-4283-9a51-3a56ccc71716","body":"木崎宿の色地蔵は、八木節の元歌と伝えられる木崎音頭の歌詞に登場する石地蔵です。長命寺門前右の小堂で、八木節へつながる木崎宿の歴史をたどってみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.ota.gunma.jp/page/4418.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"638afedf-69be-40d0-b926-20185e1f7aa8","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"c10730a4-ef4f-4b58-a989-1e04a05cb1e1","body":"水上谷川 スキーと登山","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"13e5a60d-c313-459f-ab9c-eedda0fb09d1","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"c11b10c0-1fa6-43df-b971-6e5e22fb5f6b","body":"草津では豊富な温泉が暮らしと町の形をつくってきました。湯畑は温泉街の中心で、湯を冷ましながら湯の花を採る仕組みも草津らしい温泉文化を伝えています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"a3f5948a-b9bf-4a34-a9a0-0fd102fa597a","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"c3609da7-8f44-4d7c-80c1-05cc9f191944","body":"「た」は、片品川の渓谷にある吹割の滝を詠んでいます。川床の岩盤が大きく割れたような場所へ水が流れ込む独特の姿で知られる景勝地です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"e08b235d-f74c-46ca-baa1-66a760ab4dfb","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"c45a1df8-9cad-4c2b-8a64-b4f8cd9e0970","body":null,"role":"picture_card","title":"絵札","alt_text":"茂林寺の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"6dfb7057-9b58-4a8e-ae36-62158fceed01","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ふ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"c4cf8ceb-faf9-4588-8291-c1ad3c8b5a2e","body":"東善寺では、小栗上野介に関する資料や史跡を通して札の背景をたどれます。参拝時間や拝観の案内は公式サイトで確認してください。境内や墓所では静かに参拝し、立入禁止区域には入らないでください。東善寺は「ら」の公式指定地ではなく、歴史的背景に基づくアプリ独自の訪問先です。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":"https://www.tozenzi.com/zztera.htm","metadata":{"sources":["https://www.tozenzi.com/zztera.htm","https://www.city.takasaki.gunma.jp/site/sightseeing/78704.html"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"2965782c-4ab1-420c-bb73-2a5e89ecc1ae","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-10-05T13:28:24.213679+00:00","display_order":40},{"id":"c54be14f-d302-4be6-9727-624ef857375e","body":null,"role":"picture_card","title":"絵札","alt_text":"群馬県立歴史博物館の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"3aaacece-c523-42a0-978f-e8c609800f0a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ち-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"c62bf81a-62ac-4374-8ea3-f82e7e0eb26b","body":"国指定史跡です。隣接する天神山古墳とあわせて見学できます。現地の案内表示と立入制限に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"abc8bf9c-db84-423e-bcb1-26ad18a720cd","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:09:16.324585+00:00","display_order":20},{"id":"c6e145e2-db03-478a-9966-a075b3b5ae42","body":"専用駐車場があり、そこから徒歩で見学できます。史跡内では現地の案内表示に従い、墳丘や周辺環境を傷つけないよう見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"d7cf4cf2-dc0f-4665-8ef8-c6c1b3118934","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:09:16.324585+00:00","display_order":20},{"id":"c7050916-a6f8-4a06-9edd-172cb457a81d","body":"四万温泉には「四万の病を癒す」という名の由来にまつわる伝承があり、長く療養と休養の場として利用されてきました。木造旅館などが残り、温泉地の歴史的な雰囲気を伝えています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"432cd618-9f42-4472-82df-7f3cbe744eac","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"c7349526-3086-4eda-85b0-bbc0695fff85","body":"草津よいとこ 薬の温泉","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"a3f5948a-b9bf-4a34-a9a0-0fd102fa597a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"cadaa2fd-5954-484e-9ea7-1dd262ca4019","body":"白衣大観音は昭和初期、高崎の発展や戦没者慰霊などへの願いを込めて建立されました。観音山の観光開発とともに、高崎を象徴する景観として定着していきました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"fbfbbed2-218d-483b-a6bf-37b96ec3411d","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"cb7fb976-5616-43d2-bbb0-0ee585f93511","body":null,"role":"reading_card","title":"読み札","alt_text":"ての読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"1f959c33-ef14-4fed-b456-a905ba73c009","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/て-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"cbb97e6a-5de5-4764-b2a7-377857822559","body":"大室古墳群を構成する6世紀後半の前方後円墳。墳丘長85メートルで、横穴式石室を備えています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"de8cdf05-ccb5-478f-8a62-f96ba8393d47","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"cc542cd9-5b28-4729-b444-13d8911d5740","body":null,"role":"picture_card","title":"絵札","alt_text":"安中原市杉並木の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"55a8c060-fbb2-4ae0-9f98-b4d01e823641","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/な-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"cc7a44c5-22d4-4ea1-b187-34bf81c57970","body":null,"role":"picture_card","title":"絵札","alt_text":"田山花袋旧居の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"865acdc4-13bd-4f04-b3b5-2713d5353acc","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ほ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"cc959782-056d-486a-a429-58226811a20b","body":"大室古墳群を構成する6世紀後半の前方後円墳。墳丘長38メートルで、前二子・中二子・後二子とともに大室公園内で古墳群の変遷をたどれます。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"68a99045-372f-4553-9c5e-eefa22d03a62","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"ccfd71a8-c309-46ed-abe4-80898e8d52b9","body":"「ろ」は、明治期の農業改良に尽力した船津傳次平を詠んでいます。「老農」と呼ばれ、長年の経験と実践知を生かして農業技術の普及に取り組みました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"ccf4aea3-f9f9-49b4-9064-823317e2a571","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"cd256d00-57a0-45f7-8625-aa347599dba0","body":"「せ」は、尾瀬沼と湿原に広がる花々の景観を詠んでいます。尾瀬は群馬・福島・新潟・栃木にまたがる山岳湿地で、貴重な自然環境が守られています。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"d7f6c54a-54cd-4716-afef-1823b5b8883a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"ce879501-efe6-4893-9e8f-8a9b7453e741","body":"妙義神社の参道側から妙義山を見上げ、鋭い岩峰の輪郭と季節の山肌を観察してみましょう。自然の奇岩景観と山岳信仰の場が近接していることも、この場所ならではの特徴です。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"f775a89b-f08f-431f-986c-dbf4152db415","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"cea2a87b-bcde-4eab-a008-7d7d23905da8","body":"山上碑とともに見学できる国特別史跡です。見学は無料で、駐車場があります。碑の手前には長い階段があるため足元に注意してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"37174a4c-e9e1-4b83-8dda-458f027c1246","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:42.468916+00:00","display_order":20},{"id":"ceeb1573-3b65-4050-8a32-9bdb2795fcd7","body":null,"role":"reading_card","title":"読み札","alt_text":"もの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"f775a89b-f08f-431f-986c-dbf4152db415","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/も-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"cfcf985c-dbee-40b9-9e9c-55ffd902699f","body":"1333年、新田義貞は鎌倉幕府討伐の兵を挙げ、鎌倉へ進軍しました。地域には挙兵伝承や新田氏に関係する史跡が残り、中世の東国武士の歴史を伝えています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"d46c78a7-28a2-4ed5-ac94-7b4f3638d425","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"d0142318-c3aa-4d5c-ac9b-b6a3657bd145","body":"高崎だるまの起源は、天明の飢饉後の農民救済と結び付いています。少林山達磨寺の和尚が達磨大師の姿をもとに木型を作り、農家に張り子だるまを副業として作らせ、七草大祭で売らせたことが始まりと伝えられています。上州の乾燥した冬の気候も張り子づくりに適し、農閑期の仕事として広がりました。縁起物としてのだるまの背景には、地域の暮らしを支える産業の歴史があります。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.takasaki.gunma.jp/site/sightseeing/4374.html","https://www.city.takasaki.gunma.jp/site/cultural-assets/5358.html","https://www.city.takasaki.gunma.jp/uploaded/attachment/6705.pdf"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"f5d99680-ca79-4b71-98f7-c1a34e8862f9","created_at":"2026-09-21T01:34:56.45621+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":25},{"id":"d0c4e735-f520-4612-ace3-ae142b01512c","body":"「れ」は、鎌倉幕府滅亡に大きな役割を果たした武将・新田義貞を詠んでいます。新田氏は現在の太田市周辺を本拠とした武士団です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"d46c78a7-28a2-4ed5-ac94-7b4f3638d425","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"d124a8cf-1d95-4a2c-be75-56f622b86127","body":"二子山古墳では、まず墳丘の大きさと周囲の地形を見てください。説明板や出土品の情報と合わせると、土の山に見える古墳が、古代社会の権力や技術を示す巨大な記録に変わって見えてきます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"efa7bd9c-2294-41ee-86ef-b4e06d85accd","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"d1bd987b-a57f-463d-a0ce-5197b0c91b7e","body":"県指定史跡として見学できます。小規模な古墳なので周辺の土地へ踏み込まず、現地の案内表示と見学可能範囲を守ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"6b25fea6-cd3f-4d77-afbb-4ef676f46b86","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:11:52.153716+00:00","display_order":20},{"id":"d2494f2c-5c1a-48ac-ba83-ac6d36dce941","body":null,"role":"reading_card","title":"読み札","alt_text":"せの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"d7f6c54a-54cd-4716-afef-1823b5b8883a","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/せ-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"d274114f-07e7-472f-aabb-1ebd05b241b7","body":"「ゆ」は、上野国一之宮として古くから信仰を集める一之宮貫前神社を詠んでいます。長い参道と独特な境内配置を持つ、群馬を代表する古社です。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"2432646f-411c-4990-82b4-b311a88c03e7","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"d29ffd55-c39a-4145-b22e-22610cb70335","body":"「め」は、伊勢崎銘仙で栄えた伊勢崎を詠んでいます。銘仙は鮮やかな色柄で人気を集め、近代の庶民の着物文化を彩りました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"cc638170-bf1a-4342-bada-b6e838686b53","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"d2d86df3-846f-4afb-b811-58986e423066","body":"「く」は、日本を代表する温泉地の一つ、草津温泉を詠んでいます。強い酸性の湯で知られ、古くから湯治の地として多くの人を迎えてきました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"a3f5948a-b9bf-4a34-a9a0-0fd102fa597a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"d68874e4-a43c-473e-90d6-1b7d1594d9f6","body":"利根は 坂東一の川","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"58d0874f-2e34-4884-af02-524d77b13b37","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"d78aa80c-64a2-4e09-8a7f-3dfd5653c9e9","body":null,"role":"reading_card","title":"読み札","alt_text":"にの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"9e232a01-721f-47df-b253-4a23b86f4312","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/に-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"da444171-51fb-4951-a40a-9815fc171b6a","body":"理想の電化に 電源群馬","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"cd669926-926a-4794-b11c-73f8b7b09b9e","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"da5f7541-577e-47b9-95db-4af41399811c","body":"ゆかりは古し 貫前神社","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"2432646f-411c-4990-82b4-b311a88c03e7","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"ded6a37b-5a52-45b3-a733-30d4b40ad7f2","body":"5世紀後半から6世紀初めの保渡田古墳群を構成する約100メートルの前方後円墳。出土した馬具などの国重要文化財の一部は、隣接するかみつけの里博物館で展示されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"b3d85f5e-c4a2-40d7-a6f4-61f4a339033b","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"e0af334b-3f64-4fa0-8503-d321de635c9e","body":"5世紀前半に築かれた墳丘長210メートルの前方後円墳。東日本最大の規模を誇り、長持形石棺や多様な埴輪が確認されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"d7cf4cf2-dc0f-4665-8ef8-c6c1b3118934","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"e1ed3a18-8f7b-4449-94eb-3ae8be2ecde5","body":"6世紀初めの榛名山噴火後に築かれ、6世紀中頃の噴火による軽石に埋もれた直径9メートルの円墳。横穴式石室から人骨5体や直刀、玉類などが出土しました。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"6b25fea6-cd3f-4d77-afbb-4ef676f46b86","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"e22844c4-c9f8-434e-a78b-87b11c4d10b7","body":"古墳時代後期の6世紀初頭に築かれた全長約80メートルの前方後円墳。関東でも最古級の横穴式石室をもち、人物・馬などの埴輪や豊富な副葬品が確認されています。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"85e33022-6474-4ec5-a14d-ce2a026af545","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"e36e3235-0e03-4bca-9eaf-59e61a4c88c6","body":"原市の杉並木では、木そのものだけでなく道路の方向と幅にも注目してください。ここを江戸時代の旅人や荷物が行き交ったと想像し、安中宿や碓氷関所とつなげて歩くと街道の物語になります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"55a8c060-fbb2-4ae0-9f98-b4d01e823641","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"e6b46b1f-7785-46be-b023-52daccbce6ce","body":null,"role":"picture_card","title":"絵札","alt_text":"伊香保温泉石段街の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"077359b4-482a-4d66-897f-93e8f6b34153","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/い-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"e6f38b80-00b5-4e80-8d1e-8f0fbfa32dd1","body":null,"role":"picture_card","title":"絵札","alt_text":"吹割の滝の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"e08b235d-f74c-46ca-baa1-66a760ab4dfb","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/た-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"e80d15c2-7c20-43e5-a900-965e6263f0af","body":"塚廻り古墳公園として復元整備され、自由に見学できます。公園の見学経路を利用し、復元された墳丘や埴輪を傷つけないように見学してください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"298a8d36-b28c-4028-9d53-f4b9bcc6dfaf","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:11:52.153716+00:00","display_order":20},{"id":"e84d4c42-df86-45a7-9201-457e2c3499e1","body":"吾妻峡は川の侵食によって形成された深い谷で、長い時間をかけた地質作用を目の前で見ることができます。交通やダム整備など人の営みとも関わりながら景観が受け継がれています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"e92c413a-14c5-46d1-814b-35bd537939f0","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"e9219dd2-43b3-434c-897c-acd3e8c6c2cc","body":"「り」は、豊富な水資源を利用した水力発電など、群馬の電源開発を詠んでいます。山地と河川の高低差は発電に適し、県内各地に発電施設が整備されました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"cd669926-926a-4794-b11c-73f8b7b09b9e","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"eab06859-0de5-44c0-93e7-3d1badccc4c7","body":"新島襄はキリスト教精神に基づく教育を志し、自ら考え行動する人材の育成を目指しました。鎖国の余韻が残る時代に海外へ出た経験は、その教育思想の大きな基盤となりました。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"10c77873-d75d-471c-99d4-737f4130c99c","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"eac6899a-c14b-4038-9a33-7af14b483382","body":null,"role":"picture_card","title":"絵札","alt_text":"桜山公園の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"943686a4-a533-4e8c-bcb5-5a182e10984f","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/さ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"ebd78f9d-7144-42c4-8405-c8d034246f53","body":"仙境尾瀬沼 花の原","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"d7f6c54a-54cd-4716-afef-1823b5b8883a","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"ecca4cab-ae59-4145-9c2f-e9bb920456be","body":null,"role":"reading_card","title":"読み札","alt_text":"やの読み札","link_url":null,"metadata":{"aspect_ratio":0.8030803080308031},"is_active":true,"block_type":"image","content_id":"e92c413a-14c5-46d1-814b-35bd537939f0","created_at":"2026-10-08T16:47:28.695031+00:00","media_path":"assets/karuta/読み札/や-読み札.jpg","updated_at":"2026-10-08T16:47:28.695031+00:00","display_order":1},{"id":"ecd77e78-64bc-468e-b476-face38e5dee5","body":"紅葉に映える 妙義山","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"f775a89b-f08f-431f-986c-dbf4152db415","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"ed890081-dc8c-44ca-9d2a-0ef00b7e4c9f","body":"観音像の足元ではまず大きさを体感し、市街地側から見た姿との違いを比べてみましょう。胎内に入れる場合は内部の仏像や窓からの眺めにも注目すると、建造物としての特徴も分かります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"fbfbbed2-218d-483b-a6bf-37b96ec3411d","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"edbbacfc-4696-4f8c-a22f-4734639d79d0","body":"「ほ」は、館林出身の作家・田山花袋を詠んでいます。日本の自然主義文学を代表する作家の一人で、「蒲団」「田舎教師」などの作品で知られます。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"865acdc4-13bd-4f04-b3b5-2713d5353acc","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"f001e1a4-8cfe-4255-a9c4-ef6b46d6cda0","body":"関孝和像では、刀や政治ではなく「数学」で歴史に名を残した人物であることに注目してください。藤岡周辺のゆかりをたどりながら、江戸時代にも高度な数学研究が行われていたことを想像すると札の印象が変わります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"2fb9ce0f-ebb8-417b-ae1d-bb2e7eecbed1","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"f0f023d7-e86e-454c-a54f-7a9ce9826c5b","body":"「ね」は、下仁田を代表する農産物の下仁田ねぎとこんにゃくを詠んでいます。土地の気候や農業の積み重ねが、地域名そのものを冠した名産を育てました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"c7585385-eb06-4f18-8762-21db4110c156","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"f2ad53f6-7faa-4f58-9180-f20e4a7a2fff","body":"5世紀前半頃に築かれた全長168メートルの大型前方後円墳。太田市内で天神山古墳に次ぐ規模をもち、墳丘の平坦面には円筒埴輪が並べられていました。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"9e8a430e-aa4c-4c04-b71f-18fe035c2123","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"f34c9b66-fe4f-4e1e-94e0-3f58aed8056d","body":"総社古墳群を構成する7世紀前半の古墳。古墳群が前方後円墳から大型方墳へ移る時期を伝えます。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"1244fe03-eb52-40ea-b602-71e85dd8e75b","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"f34ce104-c136-4304-885c-27049d60c265","body":"茂左衛門地蔵尊千日堂では、像や由緒、奉納物などを見てみましょう。英雄の史跡としてだけでなく、長く地域の人が祈り、物語を受け継いできた場所として見ると理解が深まります。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"1f959c33-ef14-4fed-b456-a905ba73c009","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"f41aa6a1-9b52-4a04-a159-7388b02ea269","body":null,"role":"picture_card","title":"絵札","alt_text":"生品神社の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"d46c78a7-28a2-4ed5-ac94-7b4f3638d425","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/れ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"f555d1f0-ce60-4824-bc11-4163aeb1faa3","body":"いせさき明治館では、伊勢崎銘仙をはじめとする織物文化に注目してみましょう。色柄や資料から、伊勢崎の町を支えた職人・商人・養蚕農家のつながりをたどることができます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"cc638170-bf1a-4342-bada-b6e838686b53","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"f55e6545-fa12-4755-8695-56e5dc9c30cb","body":"しのぶ毛の国 二子塚","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"efa7bd9c-2294-41ee-86ef-b4e06d85accd","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"f5615625-ad8c-4a4c-9a34-c8d6c4e2ceac","body":null,"role":"picture_card","title":"絵札","alt_text":"さちの池の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"abf5e22e-43e5-4ad0-a255-73bde912bb8d","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/つ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"f5c6d8ec-8de4-46b9-83f6-c1aa953db62f","body":"三平下は、大清水から三平峠を越えて尾瀬沼へ入る地点です。木道や登山道では植生を傷めないようルールを守り、尾瀬沼と湿原の自然を実際に歩いて体験しましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://oze-fnd.or.jp/ozb/route/route5/r1/","https://oze-fnd.or.jp/ozb/route/route5/r2/"],"visibility":"after_collection","safety_status":"public_access_caution"},"is_active":true,"block_type":"text","content_id":"d7f6c54a-54cd-4716-afef-1823b5b8883a","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"f6d6bad1-81ec-451e-a6b2-28cc113af3fb","body":"湯檜曽駅周辺では線路が山と谷のどこを通っているかを地図と見比べてみましょう。列車から見えるトンネルや線形を意識すると、山を越えるための土木技術を体感できます。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"c825159c-ceac-4323-953a-ce239e4513fa","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"f73aeec2-f253-4d7e-9ba6-1f705cc5f513","body":"花山公園 つつじの名所","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"990ef3f1-ee33-4f8e-a1e2-62481553f455","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"f88b3567-39ff-4953-a440-2dcee39c3d04","body":"南下古墳公園内で見学できます。安全確保のため石室内への立ち入りは制限されています。公園の見学経路と現地表示に従ってください。","role":"field_guide","title":"現地ガイド","alt_text":null,"link_url":null,"metadata":{"safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"e924aad0-6d27-46d8-82e3-731d21f14011","created_at":"2026-09-24T15:08:12.908738+00:00","media_path":null,"updated_at":"2026-09-24T15:10:53.140508+00:00","display_order":20},{"id":"f88bc915-8d7e-4b15-8c43-278a82b80041","body":"ループで名高い 清水トンネル","role":"reading","title":"読み札","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"]},"is_active":true,"block_type":"text","content_id":"c825159c-ceac-4323-953a-ce239e4513fa","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":10},{"id":"f95e14e6-197f-45c6-b160-bd4b2a79a895","body":"群馬県立日本絹の里では、養蚕から製糸、染織まで、群馬の絹産業を一連の文化として学べます。「繭と生糸は日本一」という札を、一つの工場ではなく県内各地の養蚕・製糸・織物へ広がる産業として見てみましょう。","role":"field_guide","title":"現地で歴史をたどる","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection","safety_status":"managed_site"},"is_active":true,"block_type":"text","content_id":"962bfffe-f2ee-4af0-a3bb-3b5fbdc5f132","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":40},{"id":"fa40eccb-de45-49c2-a86d-e91735d9a662","body":"「ふ」は、昔話「分福茶釜」で知られる館林の茂林寺を詠んでいます。寺と茶釜の伝説が結び付き、全国的に知られる物語の舞台となりました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"6dfb7057-9b58-4a8e-ae36-62158fceed01","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":20},{"id":"fb39f552-824f-4ee9-9a69-5593c9598d82","body":"「い」の札は、榛名山の東麓にある伊香保温泉を詠んでいます。伊香保は古くから知られる温泉地で、万葉集にも伊香保を詠んだ歌が残ります。江戸時代には保養地として栄え、明治以降は政財界人や文人、外国人も訪れる避暑地として全国に名を広めました。","role":"description","title":"札の由来","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.city.shibukawa.lg.jp/kankou/000357/000359/p000204.html","https://www.city.shibukawa.lg.jp/kankou-site/kankou/000357/000360/p000206.html"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"077359b4-482a-4d66-897f-93e8f6b34153","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":null,"updated_at":"2026-09-21T01:34:56.45621+00:00","display_order":20},{"id":"fbceb0a8-e761-4378-86c0-7e64f83571d8","body":"5世紀前半に築かれた全長125メートルの前方後円墳。三段築成の墳丘には葺石と大型円筒埴輪が確認され、後円部頂上には県指定重要文化財の長持形石棺があります。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"6173eb40-396f-4b9e-a2b8-d48abe5949f3","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"fcab0208-12e8-48a4-8bc3-7abe7fa6a370","body":"妙義山は火山活動と長い侵食によって現在の複雑な岩峰景観が形成されました。信仰の対象でもあり、妙義神社など山麓の文化と結び付いています。","role":"history","title":"歴史をひもとく","alt_text":null,"link_url":null,"metadata":{"sources":["https://www.pref.gunma.jp/page/3813.html","https://www.pref.gunma.jp/page/3789.html","https://jomo-karuta.com/cards/"],"visibility":"after_collection"},"is_active":true,"block_type":"text","content_id":"f775a89b-f08f-431f-986c-dbf4152db415","created_at":"2026-09-21T01:37:59.481642+00:00","media_path":null,"updated_at":"2026-09-21T01:37:59.481642+00:00","display_order":25},{"id":"fccaa4f8-8e35-446c-a37a-774da4927810","body":"吉岡町の南下古墳群を構成する古墳。古墳公園内で周辺のA号からD号墳などとあわせて古墳群の変遷を観察できます。","role":"description","title":"古墳ガイド","alt_text":null,"link_url":null,"metadata":{},"is_active":true,"block_type":"text","content_id":"e924aad0-6d27-46d8-82e3-731d21f14011","created_at":"2026-09-24T14:59:06.775713+00:00","media_path":null,"updated_at":"2026-09-24T15:05:57.031476+00:00","display_order":10},{"id":"ff02044d-516e-415c-9c33-0b9d18c65186","body":null,"role":"picture_card","title":"絵札","alt_text":"桐生織物記念館の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"2ab7a19f-8e1f-4f67-9fc6-d087030037e0","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/き-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30},{"id":"ff307ba6-c643-4b35-9d8a-5a737fc7f36a","body":null,"role":"picture_card","title":"絵札","alt_text":"塩原太助翁記念公園（塩原太助生家）の絵札","link_url":null,"metadata":{},"is_active":true,"block_type":"image","content_id":"82c45584-ad11-45a5-b30c-0f2f5ebd9716","created_at":"2026-09-20T22:34:41.947468+00:00","media_path":"assets/karuta/絵札/ぬ-絵札.jpg","updated_at":"2026-09-20T22:34:41.947468+00:00","display_order":30}]'::jsonb)
